// === HIER PFLEGEN ===
const CONFIG = {
  // Das Buch: Artikelnummer im JTL-Export. Positionen OHNE Artikelnummer erkennt der Flow an der Bezeichnung
  // (exakt, Groß-/Kleinschreibung egal).
  // EX-2025-12-08 (ebenfalls "Honesty 3 EXKLUSIVAUSGABE") gehört nicht dazu und ist bewusst NICHT eingetragen.
  targets: [
    { sku: 'EX-2026-02-03', bezeichnung: 'Honesty 3 EXKLUSIVAUSGABE' },
  ],

  // Bestellungen, die dieser Flow nicht bearbeitet: regulärer Ausdruck auf die Bestellnummer -> AUSGESCHLOSSEN
  ausschliessen: [
    { muster: '^BB-', grund: 'Shopify-Bestellung – läuft über den Shopify-Flow' },
    { muster: '^A-', grund: 'A-Auftrag – wird nicht bearbeitet' },
  ],

  // NUR_EINORDNEN = nur die CSV auswerten und Beträge berechnen, PayPal und Mollie werden nicht aufgerufen
  // TROCKENLAUF   = zusätzlich PayPal und Mollie lesen (Zahlung suchen und prüfen), es wird nichts erstattet oder ausgezahlt
  // SCHARF        = erstatten bzw. auszahlen
  modus: 'SCHARF',

  // === Debugging ===
  // Nur diese Bestellnummern bearbeiten, z. B. ['1808742', '1809038']. Leer = alle aus dem Export.
  nurBestellungen: ['1808782'],
  // Im Modus SCHARF nur so viele Erstattungen/Payouts je Zahlungsweg (PayPal, Mollie) ausführen. Alle übrigen
  // Bestellungen werden trotzdem geprüft und stehen als NICHT_VERARBEITET mit dem geplanten Betrag im Report. 0 = alle.
  testLimit: 1,

  // === Zahlungsweg (Spalte zahlungsart) ===
  // Ein Teil des Werts genügt, Groß-/Kleinschreibung egal. Transaktions-IDs mit tr_ oder ord_ gelten immer als Mollie.
  // PayPal-Liste, leere Zahlungsart und Export ohne Spalte zahlungsart: erst PayPal-Suche, was PayPal nicht findet, sucht Mollie.
  // "Karte" steht in der PayPal-Liste, damit die Kartenzahlungen bei beiden gesucht werden.
  // Passt keine Liste (z. B. Amazon Payments, Überweisung, Rechnung) -> ZAHLUNGSART_UNBEKANNT (manuell).
  zahlungsartenMollie: ['mollie'],
  zahlungsartenPayPal: ['paypal', 'karte'],

  // === PayPal ===
  // Sandbox: https://api-m.sandbox.paypal.com · Live: https://api-m.paypal.com
  // Die echten WooCommerce-Zahlungen gibt es nur im Live-System.
  paypalBaseUrl: 'https://api-m.paypal.com',

  // Rechnungsnummer bei PayPal = Präfix + Bestellnummer, z. B. "Bestellung 1808742" – das Leerzeichen gehört dazu.
  // Ermittelt am 20.10.2026 mit dem Workflow "PayPal-Rechnungspraefixe-ermitteln" (34 von 34 Treffern).
  // Die WooCommerce-PayPal-Zahlungen liefen über Mollie: im PayPal-Feld custom_field steht die Mollie-ID (tr_…).
  rechnungsPraefix: 'Bestellung ',

  // Gesucht wird je Bestellung vom Vortag bis so viele Tage nach dem Bestelldatum
  suchPufferTage: 14,
  // PayPal liefert je Suche höchstens 10.000 Transaktionen, erlaubt höchstens 31 Tage je Suche und kennt keinen Filter
  // nach Rechnungsnummer. Darum sucht der Flow je Bestellwert: Bestellungen mit gleichem Betrag teilen sich die Suchen,
  // jede Zahlung wird nur einmal geladen. Weicht die PayPal-Zahlung vom Bestellwert ab, findet PayPal sie nicht – die
  // Bestellung geht an die Mollie-Suche (dort BETRAG_PRUEFEN bzw. NICHT_GEFUNDEN).
  // Gesucht wird Bestellwert ± betragToleranz (Euro) …
  betragToleranz: 0.01,
  // … in Abschnitten von höchstens so vielen Tagen. Kommt RESULTSET_TOO_LARGE, hier kleiner stellen (z. B. 7).
  suchfensterTage: 15,

  // PayPal erstattet nur innerhalb von 180 Tagen nach der Zahlung. Ältere Zahlungen -> Payout (wenn aktiv)
  erstattungsfristTage: 180,
  // Begründung in der Erstattung, erscheint beim Kunden (max. 255 Zeichen) – PayPal und Mollie
  notizAnKunde: 'Erstattung: Der Artikel ist leider nicht mehr lieferbar.',

  // Payouts API: erst auf true stellen, wenn PayPal Payouts für das Konto freigeschaltet hat
  // und die Protokoll-Tabelle angelegt ist. false = Zahlungen über 180 Tage landen als FRIST_ABGELAUFEN im Report.
  // Gilt auch für PayPal-Zahlungen über Mollie: Empfänger ist die PayPal-E-Mail laut Mollie bzw. PayPal-Suche.
  payoutsAktiv: true,
  payoutBetreff: 'Erstattung zu Ihrer Bestellung',
  payoutNachricht: 'Ein Artikel Ihrer Bestellung ist leider nicht mehr lieferbar. Den Betrag erstatten wir Ihnen hiermit.',

  // === Mollie ===
  // Credential "Molli API" (Bearer) an allen Mollie-Nodes. Der API-Key muss zum Website-Profil des WooCommerce-Shops gehören.
  // Ohne Mollie-ID im Export lädt der Flow die Mollie-Zahlungen und -Orders ab dem ältesten Bestelldatum und ordnet
  // über die Bestellnummer (Beschreibung, Metadaten, orderNumber) zu – Gegenprobe Betrag und Datum.
  mollieBaseUrl: 'https://api.mollie.com',
  // Mollie-Suche für Bestellungen ohne Mollie-ID (z. B. "Karte", von PayPal nicht gefunden). Sie lädt ALLE Mollie-Zahlungen
  // bis zur ältesten gesuchten Bestellung – bei uns ein Jahr, weit über 100.000 Zahlungen (Laufzeit, Speicher).
  // false = diese Bestellungen werden nicht gesucht -> NICHT_GEFUNDEN mit Hinweis (manuell). Bestellungen mit Mollie-ID
  // aus PayPal oder dem Export sind davon nicht betroffen, sie werden einzeln bei Mollie abgefragt.
  mollieSucheAktiv: false,
  // Bekannte Fristen je Mollie-Zahlart in Tagen ab Zahlung (Mollie-Hilfe): älter -> FRIST_ABGELAUFEN, manuell erstatten.
  // Ausnahme PayPal über Mollie: älter -> Payout bei PayPal (nur mit payoutsAktiv, sonst FRIST_ABGELAUFEN).
  // Für andere Zahlarten entscheidet Mollie: Bietet Mollie keinen erstattbaren Betrag mehr an -> MANUELL_ERSTATTEN.
  mollieFristTage: { creditcard: 365, paypal: 180 },

  // === Versand ===
  // Jeder Artikel einzeln verschickt (DHL Kleinpaket: 3,99 je Artikel): Buchpreis + Versandkosten ÷ Positionen
  versandartEinzel: ['Einzelversand', 'DHL Kleinpaket', 'DHL Paket'],
  versandartSammel: ['Sammelversand'],
  // Kostenloser Versand: nur der Buchpreis wird erstattet
  versandartKostenlos: ['Kostenlose Lieferung', 'Kostenlose Lieferung (Membership)'],
  // Kein Versand (Abholung): nur der Buchpreis wird erstattet
  versandartNurBuchpreis: ['Abholung'],
  // Weitere Versandarten einer Regel zuordnen, indem du sie in eine der Listen oben einträgst.
  // Nicht zugeordnet -> VERSANDART_UNBEKANNT (keine Erstattung).

  // === Prototyp: diese Fälle bearbeitet der Flow vorerst nicht, sie stehen markiert im Report ===
  // false = Sammelversand mit danach nur noch 1 Artikel -> SAMMELVERSAND_EIN_PRODUKT (manuell)
  sammelversandEinProduktBerechnen: false,
  // false = Einzelversand mit weiteren Artikeln -> EINZELVERSAND_WEITERE_ARTIKEL (manuell, Betrag als Vorschlag im Report)
  einzelversandMitWeiterenBerechnen: false,
  // false = Bestellung mit Gutschein oder Rabattcode (Position ohne Artikelnummer mit Minusbetrag) -> GUTSCHEIN (manuell),
  // auch wenn nur das Buch bestellt war
  gutscheinBestellungenBerechnen: false,
  // Bestellungen mit einer Box: eine Position enthält einen dieser Begriffe (Groß-/Kleinschreibung egal) -> BOX (manuell)
  boxBegriffe: ['box'],

  // Kosten EINER Einzelsendung je Lieferland, für Sammelversand mit danach nur noch 1 Produkt
  // (nur mit sammelversandEinProduktBerechnen: true): Erstattung = Buchpreis + bezahlter Sammelversand − dieser Betrag.
  // Schlüssel = Wert der Spalte Versandland (Kürzel). Weitere Lieferländer genauso ergänzen, z. B. NL: 9.99.
  // Fehlt der Wert -> VERSAND_PRUEFEN.
  versandkostenEinzel: { DE: null, AT: null, CH: null },

  // === JTL-Export (CSV, Ameise) ===
  // Eine Zeile je Position, Bestelldaten in jeder Zeile. Fehlt eine Spalte, nennt der Fehler alle vorhandenen.
  // Der Versand steht als eigene Zeile drin: ohne Artikelnummer, Bezeichnung = Versandart, Brutto-VK = Versandkosten.
  // Gutscheine und Rabattcodes ebenso, mit Minusbetrag. Erste Zeile = Kopfzeile mit den Spaltennamen unten.
  csvTrennzeichen: ';',
  // Währung, falls der Export keine Währungsspalte hat
  waehrung: 'EUR',
  spalten: {
    bestellnummer: 'Auftragsnummer',               // bei WooCommerce-Aufträgen = WooCommerce-Bestellnummer = PayPal-Rechnungsnummer ohne Präfix
    datum: 'Auftragsdatum',
    versandart: 'Versandart',
    land: 'Versandland',
    waehrung: 'Währung',
    bestellwert: 'Betrag',                         // Gesamtbetrag der Bestellung: Summenprüfung und Gegenprobe zum gezahlten Betrag
    versandkosten: '',                             // leer = aus der Versandzeile (siehe oben)
    artikelnummer: 'Artikelnummer',
    bezeichnung: 'Bezeichnung (Position)',
    menge: 'Menge',
    positionBrutto: 'Brutto-VK',
    positionstyp: '',                              // nur nötig, wenn der Export eine Spalte für den Positionstyp hat
    // Optional – leer = Spalte nicht vorhanden. Ohne Zahlungsart: erst PayPal, was PayPal nicht findet, sucht Mollie.
    zahlungsart: 'Zahlungsart',                    // Zahlungsweg je Bestellung (siehe zahlungsartenMollie / zahlungsartenPayPal)
    transaktionsId: ''                             // z. B. 'Transaktions-ID': wird genutzt, wenn gefüllt; sonst Suche über die Bestellnummer
  },
  // true = Brutto-VK ist der Einzelpreis (wird mit der Menge multipliziert), false = Gesamtpreis der Position.
  // Stimmt die Einstellung nicht, meldet die Summenprüfung (Positionen + Versand = Betrag) die Bestellung als DATEN_PRUEFEN.
  bruttoVkJeStueck: true,
  // Werte der Spalte positionstyp, die eine Versandposition kennzeichnen (nur mit spalten.positionstyp)
  positionstypVersand: ['Versand'],

  // Einzelne Bestellungen ausschließen: Bestellnummer
  ausnahmen: []
};

const fehler = [];
if (!CONFIG.targets.length || CONFIG.targets.some(t => !String(t.sku || '').trim())) fehler.push('SKU des Buchs fehlt');
if (!['NUR_EINORDNEN', 'TROCKENLAUF', 'SCHARF'].includes(CONFIG.modus)) fehler.push(`modus "${CONFIG.modus}" unbekannt`);
// Ohne Transaktions-ID im Export ordnet der Flow PayPal-Zahlungen über die Rechnungsnummer zu – dafür braucht er das Präfix
if (CONFIG.modus !== 'NUR_EINORDNEN' && !CONFIG.spalten.transaktionsId && CONFIG.rechnungsPraefix.includes('TODO')) {
  fehler.push('rechnungsPraefix eintragen oder spalten.transaktionsId angeben');
}
if (fehler.length) throw new Error('Config: ' + fehler.join(' · '));

// CSV-Binary unverändert durchreichen, Config für alle Folge-Nodes anhängen
return $input.all().map(i => ({
  json: { ...i.json, config: CONFIG },
  binary: i.binary
}));

// Fasst den JTL-Export (eine Zeile je Position) zu Bestellungen zusammen und berechnet je Bestellung den Erstattungsbetrag.
// Ergebnis: Kandidat (toFix) oder übersprungen (skipped). Ohne API-Aufrufe.
const config = $('Config').first().json.config;
const S = config.spalten;
// Bereinigen: unsichtbares BOM-Zeichen vor dem ersten Spaltennamen, Apostroph vor Werten ('19,90 – im älteren Export
// auch dahinter: '19,90') und NULL für leere Felder aus dem Ameise-Export
const sauber = v => {
  let s = String(v ?? '').trim();
  if (s.startsWith("'")) s = s.slice(1).replace(/'$/, '');
  return s === 'NULL' ? '' : s;
};
const rows = $input.all().map(i => Object.fromEntries(
  Object.entries(i.json).map(([k, v]) => [k.replace(/^﻿/, '').trim(), sauber(v)])
));
if (!rows.length) throw new Error('JTL-Export ist leer');

// Beim ersten Lauf mit dem echten Export zeigt dieser Fehler die vorhandenen Spalten
const vorhanden = Object.keys(rows[0]);
const fehlend = Object.values(S).filter(Boolean).filter(s => !vorhanden.includes(s));
if (fehlend.length) {
  throw new Error(`JTL-Export: Spalte(n) fehlen: ${fehlend.join(', ')} – vorhanden: ${vorhanden.join(', ')}. Bitte Config.spalten anpassen.`);
}

const runden = x => Math.round(x * 100) / 100;
const text = (row, spalte) => spalte ? String(row[spalte] ?? '').trim() : '';
const norm = s => String(s || '').trim().toLowerCase();
const inListe = (wert, liste) => (liste || []).map(norm).includes(norm(wert));
// Zahlen: "1.234,56", "12,99" oder "12.99" – nicht lesbar = NaN
const zahl = v => {
  const s = String(v ?? '').trim().replace(/[\s€]/g, '');
  if (!s) return 0;
  return Number(s.includes(',') ? s.replace(/\./g, '').replace(',', '.') : s);
};
// Datum: "02.08.2026 19:57:47", "02.08.2026" oder ISO
const datum = v => {
  const s = String(v ?? '').trim();
  const m = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/);
  const d = m ? new Date(Date.UTC(Number(m[3]), Number(m[2]) - 1, Number(m[1]))) : new Date(s);
  return s && !isNaN(d) ? d : null;
};

// Zeilen derselben Bestellnummer zusammenfassen (müssen nicht untereinander stehen)
const bestellungen = new Map();
for (const row of rows) {
  const nr = text(row, S.bestellnummer);
  if (!nr) continue;
  if (!bestellungen.has(nr)) bestellungen.set(nr, []);
  bestellungen.get(nr).push(row);
}
if (!bestellungen.size) throw new Error(`JTL-Export: keine Zeile mit Bestellnummer (Spalte "${S.bestellnummer}")`);

// Zum Testen und Debuggen: nur die Bestellnummern aus Config.nurBestellungen bearbeiten
const nur = (config.nurBestellungen || []).map(String);
if (nur.length) {
  for (const nr of [...bestellungen.keys()]) if (!nur.includes(nr)) bestellungen.delete(nr);
  if (!bestellungen.size) throw new Error(`Config.nurBestellungen: keine dieser Bestellnummern im Export (${nur.join(', ')})`);
}

const ZIEL_SKUS = new Set(config.targets.map(t => String(t.sku).trim()));
// Buch in Positionen ohne Artikelnummer: über die Bezeichnung, gezählt unter der Artikelnummer aus targets
const ZIEL_NACH_NAME = new Map(config.targets.filter(t => t.bezeichnung).map(t => [norm(t.bezeichnung), String(t.sku).trim()]));
const staticData = $getWorkflowStaticData('global');
staticData.toFix = [];
staticData.skipped = [];
staticData.done = [];
// Zähler für die Lauf-Info in der Report-Mail und Zwischenstände der PayPal-/Mollie-Suche
staticData.lauf = {};
staticData.paypalNichtGefunden = [];
staticData.paypalMollie = [];
staticData.mollieDirekt = [];
staticData.mollieSuche = [];

// Brutto der Position: Brutto-VK je Stück × Menge (bruttoVkJeStueck) oder schon der Gesamtpreis
const position = r => {
  const menge = zahl(r[S.menge]);
  const preis = zahl(r[S.positionBrutto]);
  const sku = text(r, S.artikelnummer);
  const title = text(r, S.bezeichnung);
  return {
    sku: sku || ZIEL_NACH_NAME.get(norm(title)) || '',
    title,
    ohneArtikelnummer: !sku,
    menge,
    brutto: runden(preis * (config.bruttoVkJeStueck && menge > 0 ? menge : 1))
  };
};
// Artikel: mit Artikelnummer, oder ohne Artikelnummer mit Bezeichnung und Preis > 0 (z. B. in den A-…-Aufträgen)
const istArtikel = p => p.menge > 0 && Boolean(p.sku || (p.title && p.brutto > 0));
const alleVersandarten = [
  ...config.versandartEinzel, ...config.versandartSammel, ...config.versandartKostenlos, ...(config.versandartNurBuchpreis || [])
];

for (const [nr, zeilen] of bestellungen) {
  const erster = spalte => zeilen.map(r => text(r, spalte)).find(Boolean) || '';
  const versandartKopf = erster(S.versandart);
  // Versandzeile: über die Spalte positionstyp, sonst Zeile ohne Artikelnummer mit einer Versandart als Bezeichnung
  const istVersandZeile = r => S.positionstyp
    ? inListe(text(r, S.positionstyp), config.positionstypVersand)
    : !text(r, S.artikelnummer) && inListe(text(r, S.bezeichnung), [...alleVersandarten, versandartKopf]);
  const versandZeilen = zeilen.filter(istVersandZeile);
  const pos = zeilen.filter(r => !istVersandZeile(r)).map(position);
  const artikel = pos.filter(istArtikel);
  // Positionen ohne Artikelnummer, die keine Artikel sind, mit Betrag – z. B. Gutscheine (negativ)
  const sonstige = pos.filter(p => !p.sku && !istArtikel(p) && p.brutto !== 0);
  const buch = artikel.filter(p => ZIEL_SKUS.has(p.sku));
  const weitere = artikel.filter(p => !ZIEL_SKUS.has(p.sku));
  const versandkosten = S.versandkosten
    ? zahl(erster(S.versandkosten))
    : runden(versandZeilen.map(position).reduce((s, p) => s + p.brutto, 0));
  const summePositionen = runden(pos.reduce((s, p) => s + p.brutto, 0) + versandkosten);
  const bestellwertSpalte = S.bestellwert ? erster(S.bestellwert) : '';
  const bestellwert = bestellwertSpalte ? zahl(bestellwertSpalte) : summePositionen;
  const bestellt = datum(erster(S.datum));
  const land = erster(S.land);
  const versandart = versandartKopf || versandZeilen.map(r => text(r, S.bezeichnung)).find(Boolean) || '';

  // Zahlungsweg: Mollie an der Transaktions-ID (tr_/ord_) oder an der Zahlungsart, sonst PayPal laut Zahlungsart.
  // PAYPAL heißt: erst PayPal-Suche, was PayPal nicht findet, sucht danach Mollie. Das gilt auch ohne Spalte zahlungsart
  // und bei leerer Zahlungsart. Passt nichts -> '' (ZAHLUNGSART_UNBEKANNT).
  const zahlungsart = erster(S.zahlungsart);
  const transaktionsIdExport = erster(S.transaktionsId);
  const enthaelt = (wert, liste) => (liste || []).some(z => norm(wert).includes(norm(z)));
  const zahlungsweg = /^(tr|ord)_/.test(transaktionsIdExport) || enthaelt(zahlungsart, config.zahlungsartenMollie) ? 'MOLLIE'
    : !S.zahlungsart || !zahlungsart || enthaelt(zahlungsart, config.zahlungsartenPayPal) ? 'PAYPAL'
    : '';

  const datensatz = {
    zahlungsart,
    zahlungsweg,
    transaktionsIdExport,
    bestellnummer: nr,
    bestelldatum: bestellt ? bestellt.toISOString().slice(0, 10) : '',
    land,
    waehrung: erster(S.waehrung) || config.waehrung,
    bestellwert,
    versandart,
    versandkosten,
    buchWert: runden(buch.reduce((s, p) => s + p.brutto, 0)),
    skus: [...new Set(buch.map(p => p.sku))],
    positionen: buch,
    weitere,
    sonstige,
    // Für den Report: alle Positionen und Versandzeilen der Bestellung
    positionenAlle: pos.map(({ title, sku, menge, brutto }) => ({ title, sku, menge, brutto })),
    versandZeilen: versandZeilen.map(position).map(({ title, brutto }) => ({ title, brutto }))
  };

  const ergebnis = (() => {
    // Bestellungen anderer Flows, z. B. Shopify
    const ausschluss = (config.ausschliessen || []).find(a => new RegExp(a.muster).test(nr));
    if (ausschluss) return { status: 'AUSGESCHLOSSEN', grund: ausschluss.grund };

    if ([...pos.flatMap(p => [p.menge, p.brutto]), versandkosten, bestellwert].some(Number.isNaN)) {
      return { status: 'DATEN_PRUEFEN', grund: 'Menge oder Betrag im Export nicht lesbar' };
    }
    if (!bestellt) return { status: 'DATEN_PRUEFEN', grund: 'Bestelldatum fehlt oder ist nicht lesbar – nötig für die PayPal-Suche' };
    if ((config.ausnahmen || []).map(String).includes(nr)) {
      return { status: 'AUSNAHME', grund: 'Bestellung steht in Config.ausnahmen' };
    }
    if (!buch.length) return { status: 'NICHT_BETROFFEN', grund: 'Buch nicht in der Bestellung – Export prüfen' };

    // Prototyp: Bestellungen mit einer Box (z. B. Spezialbox, Einzelbox) bearbeitet der Flow vorerst nicht
    const box = pos.find(p => (config.boxBegriffe || []).some(b => norm(p.title).includes(norm(b))));
    if (box) return { status: 'BOX', grund: `Box in der Bestellung (${box.title}) – vorerst manuell bearbeiten` };

    // Summenprüfung: Positionen + Versand müssen den Gesamtbetrag ergeben,
    // sonst fehlen Zeilen oder Brutto-VK ist anders zu lesen (Config.bruttoVkJeStueck)
    if (bestellwertSpalte && Math.abs(summePositionen - bestellwert) > 0.01) {
      return {
        status: 'DATEN_PRUEFEN',
        grund: `Positionen + Versand = ${summePositionen.toFixed(2)}, Betrag laut Export ${bestellwert.toFixed(2)} – fehlende Zeilen oder bruttoVkJeStueck prüfen`
      };
    }

    // Buch ohne eigenen Preis, z. B. als Bestandteil einer Box: Erstattungsbetrag nicht ableitbar
    if (buch.some(p => !(p.brutto > 0))) {
      return { status: 'POSITIONEN_PRUEFEN', grund: 'Buch ohne eigenen Preis (z. B. Teil einer Box) – manuell prüfen' };
    }

    // Prototyp: Bestellungen mit Gutschein oder Rabattcode bearbeitet der Flow vorerst nicht – auch nicht, wenn nur das
    // Buch bestellt war (bei einem Geschenkgutschein käme sonst nur der bar bezahlte Teil zurück)
    const gutscheine = sonstige.filter(p => p.brutto < 0);
    if (gutscheine.length && !config.gutscheinBestellungenBerechnen) {
      return {
        status: 'GUTSCHEIN',
        grund: `Gutschein/Rabattcode in der Bestellung (${gutscheine.map(p => `${p.title || '?'} ${p.brutto.toFixed(2)}`).join(', ')}) – vorerst manuell bearbeiten`
      };
    }

    // Bestellung nach dem Entfernen leer: alles erstatten
    if (!weitere.length) return { aktion: 'ALLES', fall: 'NUR_BUCH', versandErstattung: null };

    // Weitere Produkte: Buchpreis + ggf. Versandanteil
    if (sonstige.length) {
      return {
        status: 'POSITIONEN_PRUEFEN',
        grund: `Weitere Positionen (${sonstige.map(p => p.title || p.brutto).join(', ')}) – Buchwert nicht eindeutig, manuell prüfen`
      };
    }

    if (inListe(versandart, config.versandartKostenlos)) {
      return { aktion: 'TEIL', fall: 'KOSTENLOSE_LIEFERUNG', versandErstattung: 0 };
    }

    if (inListe(versandart, config.versandartNurBuchpreis)) {
      return { aktion: 'TEIL', fall: 'NUR_BUCHPREIS', versandErstattung: 0 };
    }

    if (inListe(versandart, config.versandartEinzel)) {
      // Jede Position wurde einzeln verschickt und hat eigene Versandkosten gekostet:
      // Kosten je Sendung = Versandkosten der Bestellung / Anzahl Artikelpositionen, erstattet werden die Sendungen des Buchs
      const sendungen = artikel.length;
      const jeSendung = runden(versandkosten / sendungen);
      // Prototyp: Einzelversand mit weiteren Artikeln (nur das Buch wäre NUR_BUCH) vorerst manuell – Betrag als Vorschlag
      if (!config.einzelversandMitWeiterenBerechnen) {
        const teilbar = versandkosten === 0 || (versandkosten > 0 && Math.abs(jeSendung * sendungen - versandkosten) <= 0.005);
        const anteil = versandkosten === 0 ? 0 : runden(jeSendung * buch.length);
        return {
          status: 'EINZELVERSAND_WEITERE_ARTIKEL',
          grund: 'Einzelversand mit weiteren Artikeln – vorerst manuell bearbeiten. ' + (teilbar
            ? `Vorschlag: Buch ${datensatz.buchWert.toFixed(2)} + Versandanteil ${anteil.toFixed(2)} (${versandkosten.toFixed(2)} ÷ ${sendungen} Positionen) = ${runden(datensatz.buchWert + anteil).toFixed(2)}`
            : `Versand ${versandkosten.toFixed(2)} lässt sich nicht gleichmäßig auf ${sendungen} Positionen aufteilen`),
          versandErstattung: teilbar ? anteil : '',
          erstattungsbetrag: teilbar ? runden(datensatz.buchWert + anteil) : ''
        };
      }
      // Kein Versand bezahlt: es gibt keinen Versand zu erstatten, nur das Buch
      if (versandkosten === 0) return { aktion: 'TEIL', fall: 'EINZELVERSAND', versandErstattung: 0 };
      if (!(versandkosten > 0)) return { status: 'VERSAND_PRUEFEN', grund: `Versandkosten ${versandkosten.toFixed(2)} im Export – manuell prüfen` };
      if (Math.abs(jeSendung * sendungen - versandkosten) > 0.005) {
        return {
          status: 'VERSAND_PRUEFEN',
          grund: `Einzelversand ${versandkosten.toFixed(2)} lässt sich nicht gleichmäßig auf ${sendungen} Positionen aufteilen – manuell prüfen`
        };
      }
      return { aktion: 'TEIL', fall: 'EINZELVERSAND', versandErstattung: runden(jeSendung * buch.length) };
    }

    if (inListe(versandart, config.versandartSammel)) {
      // Was nach dem Entfernen noch verschickt werden muss (Stückzahl)
      const restEinheiten = weitere.reduce((s, p) => s + p.menge, 0);
      if (restEinheiten >= 2) return { aktion: 'TEIL', fall: 'SAMMELVERSAND', versandErstattung: 0 };
      // Prototyp: danach nur noch 1 Artikel bearbeitet der Flow vorerst nicht (Config.sammelversandEinProduktBerechnen)
      if (!config.sammelversandEinProduktBerechnen) {
        return { status: 'SAMMELVERSAND_EIN_PRODUKT', grund: 'Sammelversand, danach nur noch 1 Artikel – im Prototyp ausgeschlossen, manuell bearbeiten' };
      }
      // Kein Versand bezahlt: es gibt keinen Versand zu erstatten, nur das Buch
      if (versandkosten === 0) return { aktion: 'TEIL', fall: 'SAMMELVERSAND_EIN_PRODUKT', versandErstattung: 0 };
      const einzel = config.versandkostenEinzel?.[land];
      if (typeof einzel !== 'number' || !Number.isFinite(einzel)) {
        return { status: 'VERSAND_PRUEFEN', grund: `Keine Einzelversandkosten für Land "${land}" in Config.versandkostenEinzel` };
      }
      if (versandkosten < einzel) {
        return { status: 'VERSAND_PRUEFEN', grund: `Sammelversand ${versandkosten.toFixed(2)} kleiner als Einzelversand ${einzel.toFixed(2)} – manuell prüfen` };
      }
      return { aktion: 'TEIL', fall: 'SAMMELVERSAND_EIN_PRODUKT', versandErstattung: runden(versandkosten - einzel) };
    }

    return { status: 'VERSANDART_UNBEKANNT', grund: `Versandart "${versandart}" – vorerst nicht bearbeitet` };
  })();

  if (ergebnis.aktion) {
    const kandidat = {
      ...datensatz,
      ...ergebnis,
      // ALLES: erstattet wird die ganze Zahlung – bis zur Abfrage beim Anbieter gilt der Bestellwert laut Export
      erstattungsbetrag: ergebnis.aktion === 'ALLES'
        ? datensatz.bestellwert
        : runden(datensatz.buchWert + ergebnis.versandErstattung)
    };
    if (zahlungsweg) staticData.toFix.push(kandidat);
    // Weder PayPal noch Mollie: Betrag steht im Report, erstattet wird von Hand
    else staticData.skipped.push({ ...kandidat, status: 'ZAHLUNGSART_UNBEKANNT', grund: `Zahlungsart "${zahlungsart || 'leer'}" – weder PayPal noch Mollie, manuell erstatten` });
  } else {
    staticData.skipped.push({ ...datensatz, ...ergebnis });
  }
}

return [{
  json: {
    paypal: config.modus !== 'NUR_EINORDNEN' && staticData.toFix.some(o => o.zahlungsweg === 'PAYPAL'),
    mollie: config.modus !== 'NUR_EINORDNEN' && staticData.toFix.some(o => o.zahlungsweg === 'MOLLIE'),
    bestellungen: bestellungen.size,
    kandidaten: staticData.toFix.length,
    uebersprungen: staticData.skipped.length
  }
}];

// Token prüfen und die PayPal-Transaktionssuchen bilden. PayPal liefert je Suche höchstens 10.000 Transaktionen
// (RESULTSET_TOO_LARGE), erlaubt höchstens 31 Tage je Suche und kennt keinen Filter nach Rechnungsnummer.
// Darum teilen sich Bestellungen mit gleichem Bestellwert die Suchen: je Betrag werden die Zeiträume der Bestellungen
// (Vortag bis +suchPufferTage) zusammengefasst und in Stücke von höchstens suchfensterTage geteilt. Gefiltert wird auf
// Bruttobetrag = Bestellwert ± betragToleranz (Filter transaction_amount, in Cent). So lädt PayPal jede Zahlung nur einmal.
const antwort = $('Token holen (PayPal)').first().json;
if (!antwort.access_token) {
  throw new Error('PayPal: kein Access-Token – Credential an "Token holen (PayPal)" prüfen. Antwort: ' + JSON.stringify(antwort).slice(0, 300));
}

const config = $('Config').first().json.config;
const sd = $getWorkflowStaticData('global');
sd.lauf = sd.lauf || {};
const TAG = 86400000;
const jetzt = Date.now();
const iso = t => new Date(t).toISOString().replace(/\.\d{3}Z$/, 'Z');
const cent = x => Math.round(x * 100);
const toleranzCent = cent(Number(config.betragToleranz) || 0);
const fensterTage = Math.min(Math.max(Number(config.suchfensterTage) || 15, 1), 31);

// Nur Bestellungen mit Zahlungsweg PayPal (Mollie läuft danach in eigener Schleife), gruppiert nach Bestellwert in Cent
const proBetrag = new Map();
for (const o of (sd.toFix || []).filter(o => o.zahlungsweg === 'PAYPAL')) {
  const c = cent(o.bestellwert);
  const d = new Date(o.bestelldatum).getTime();
  if (!proBetrag.has(c)) proBetrag.set(c, []);
  proBetrag.get(c).push({ nr: o.bestellnummer, von: d - TAG, bis: Math.min(d + (config.suchPufferTage + 1) * TAG, jetzt) });
}

const suchen = [];
for (const [c, liste] of proBetrag) {
  // Überlappende Zeiträume desselben Betrags zusammenfassen
  liste.sort((a, b) => a.von - b.von);
  const zusammen = [];
  for (const z of liste) {
    const letztes = zusammen[zusammen.length - 1];
    if (letztes && z.von <= letztes.bis) {
      letztes.bis = Math.max(letztes.bis, z.bis);
      letztes.nrs.push(z.nr);
    } else {
      zusammen.push({ von: z.von, bis: z.bis, nrs: [z.nr] });
    }
  }
  // In Stücke von höchstens fensterTage teilen
  for (const z of zusammen) {
    for (let a = z.von; a < z.bis; a += fensterTage * TAG) {
      suchen.push({
        start: iso(a),
        ende: iso(Math.min(a + fensterTage * TAG, z.bis) - 1000),
        betrag: `[${Math.max(0, c - toleranzCent)} TO ${c + toleranzCent}]`,
        // Nur zur Nachverfolgung: Bestellungen, deren Zeitraum in diesem Abschnitt liegt
        bestellungen: z.nrs.join(', ')
      });
    }
  }
}

// Für die Lauf-Info in der Report-Mail
sd.lauf.paypalSuchen = suchen.length;
sd.lauf.paypalBestellungen = [...proBetrag.values()].reduce((s, l) => s + l.length, 0);
sd.lauf.paypalBetraege = proBetrag.size;

return suchen.map(s => ({ json: s }));

// Ordnet die gefundenen PayPal-Zahlungen den PayPal-Bestellungen zu: zuerst über die Transaktions-ID aus dem Export,
// sonst über die Rechnungsnummer (Präfix + Bestellnummer). Nicht gefunden -> weiter an die Mollie-Suche.
// Zahlung über Mollie (Mollie-ID tr_… im PayPal-Feld custom_field) -> weiter an die Mollie-Schleife: Prüfen und Erstatten
// über Mollie, über 180 Tage Payout. Nur Zahlungen ohne Mollie-ID laufen durch die PayPal-Schleife (Capture, Refund, Payout).
// Nicht eindeutig zuordenbar -> Eintrag für den Report, keine Bearbeitung.
const config = $('Config').first().json.config;
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.done)) sd.done = [];
sd.lauf = sd.lauf || {};
// Was PayPal nicht findet, sucht danach die Mollie-Schleife
sd.paypalNichtGefunden = [];
// Bei PayPal gefunden, aber über Mollie bezahlt: geht mit der Mollie-ID an die Mollie-Schleife
sd.paypalMollie = [];

const vermerk = (o, status, grund, extra = {}) => sd.done.push({
  bestellnummer: o.bestellnummer, status, grund: String(grund).slice(0, 500), ...extra, bearbeitetAm: new Date().toISOString()
});

// Nur eingehende Zahlungen (positiver Betrag) – Erstattungen haben negative Beträge. Je Transaktions-ID nur ein Eintrag.
const zahlungen = new Map();
let seiten = 0;
for (const seite of $input.all()) {
  seiten++;
  for (const t of seite.json.transaction_details || []) {
    const ti = t.transaction_info || {};
    if (!ti.transaction_id || !(Number(ti.transaction_amount?.value) > 0)) continue;
    zahlungen.set(ti.transaction_id, {
      transaktionsId: ti.transaction_id,
      rechnung: String(ti.invoice_id || '').trim(),
      status: ti.transaction_status,
      datum: ti.transaction_initiation_date,
      betrag: Number(ti.transaction_amount.value),
      waehrung: ti.transaction_amount.currency_code,
      email: t.payer_info?.email_address || '',
      // Zahlungen über Mollie: Mollie-ID (tr_…) in custom_field
      custom: String(ti.custom_field || '').trim()
    });
  }
}
const perRechnung = new Map();
for (const z of zahlungen.values()) {
  if (!z.rechnung) continue;
  if (!perRechnung.has(z.rechnung)) perRechnung.set(z.rechnung, []);
  perRechnung.get(z.rechnung).push(z);
}
const mitPraefix = !String(config.rechnungsPraefix).includes('TODO');

// Für die Lauf-Info in der Report-Mail
sd.lauf.paypalSeiten = seiten;
sd.lauf.paypalZahlungen = zahlungen.size;
sd.lauf.paypalZuordnung = {};
sd.lauf.paypalMitMollieId = 0;

const items = [];
for (const o of (sd.toFix || []).filter(o => o.zahlungsweg === 'PAYPAL')) {
  const rechnungsnummer = config.rechnungsPraefix + o.bestellnummer;
  let treffer = [];
  let zuordnung = '';
  if (o.transaktionsIdExport && zahlungen.has(o.transaktionsIdExport)) {
    treffer = [zahlungen.get(o.transaktionsIdExport)];
    zuordnung = 'Transaktions-ID';
  } else if (mitPraefix && perRechnung.has(rechnungsnummer)) {
    treffer = perRechnung.get(rechnungsnummer);
    zuordnung = 'Rechnungsnummer';
  }
  sd.lauf.paypalZuordnung[zuordnung || 'keine'] = (sd.lauf.paypalZuordnung[zuordnung || 'keine'] || 0) + 1;
  const debug = `PayPal-Suche: ${zahlungen.size} Zahlungen · Zuordnung: ${zuordnung || 'keine'}`;

  if (!treffer.length) {
    const gesucht = [
      o.transaktionsIdExport ? `Transaktions-ID "${o.transaktionsIdExport}"` : '',
      mitPraefix ? `Rechnungsnummer "${rechnungsnummer}"` : ''
    ].filter(Boolean).join(' oder ') || 'nichts – weder Transaktions-ID im Export noch Präfix in der Config';
    sd.paypalNichtGefunden.push({ bestellnummer: o.bestellnummer, gesucht: `${gesucht}, Vortag bis +${config.suchPufferTage} Tage` });
    continue;
  }
  if (treffer.length > 1) {
    vermerk(o, 'TRANSAKTION_PRUEFEN', `${treffer.length} PayPal-Zahlungen mit Rechnungsnummer "${rechnungsnummer}": ${treffer.map(t => t.transaktionsId).join(', ')}`, { debug });
    continue;
  }

  const z = treffer[0];
  const info = { transaktionsId: z.transaktionsId, zahlungsdatum: z.datum, zahlungsBetrag: z.betrag, zuordnung, debug };
  // Status laut Transaktionssuche: S = abgeschlossen, P = ausstehend, V = rückgängig gemacht und erstattet, D = abgelehnt
  if (z.status === 'V') {
    vermerk(o, 'BEREITS_ERSTATTET', 'PayPal: Zahlung wurde rückgängig gemacht und erstattet (Status V)', info);
    continue;
  }
  if (z.status !== 'S') {
    vermerk(o, 'ZAHLUNG_PRUEFEN', `PayPal-Status ${z.status}`, info);
    continue;
  }
  if (z.waehrung !== o.waehrung) {
    vermerk(o, 'ZAHLUNG_PRUEFEN', `Währung bei PayPal ${z.waehrung}, im Export ${o.waehrung}`, info);
    continue;
  }
  // Gegenprobe: PayPal-Betrag = Bestellwert laut Export, sonst falsche Zuordnung oder Teilzahlung (z. B. Gutschein)
  if (Math.abs(z.betrag - o.bestellwert) > 0.01) {
    vermerk(o, 'BETRAG_PRUEFEN', `PayPal-Zahlung ${z.betrag.toFixed(2)}, Bestellwert laut Export ${o.bestellwert.toFixed(2)}`, info);
    continue;
  }

  // Über Mollie bezahlt: Prüfen und Erstatten über Mollie (Mollie kennt die Zahlung und erstattet bis 180 Tage),
  // die PayPal-Daten gehen mit – die E-Mail des Zahlers für einen Payout über 180 Tage
  const mollieId = (z.custom.match(/^(tr|ord)_\w+$/) || [])[0];
  if (mollieId) {
    sd.lauf.paypalMitMollieId++;
    sd.paypalMollie.push({
      bestellnummer: o.bestellnummer,
      mollieId,
      paypalTransaktionsId: z.transaktionsId,
      paypalDatum: z.datum,
      paypalEmail: z.email,
      debug: `${debug} · PayPal ${z.transaktionsId} über Mollie (${mollieId})`
    });
    continue;
  }

  items.push({
    json: {
      bestellnummer: o.bestellnummer,
      aktion: o.aktion,
      fall: o.fall,
      skus: o.skus,
      waehrung: o.waehrung,
      erstattungsbetrag: o.erstattungsbetrag,
      captureId: z.transaktionsId,
      zahlungsdatum: z.datum,
      zahlungsBetrag: z.betrag,
      email: z.email,
      zuordnung,
      debug
    }
  });
}

// Keine Zahlung zugeordnet: Steuer-Item ohne captureId -> IF leitet direkt weiter zu Mollie
return items.length ? items : [{ json: { zugeordnet: 0 } }];

// Prüft die Zahlung bei PayPal und wählt den Weg:
// ERSTATTUNG (Zahlung bis 180 Tage alt), PAYOUT (älter, wenn aktiv) oder KEINER (Report-Eintrag, keine Aktion).
const resp = $input.first().json;
const src = $('Loop Over Items').first().json;
const config = $('Config').first().json.config;
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.done)) sd.done = [];

const runden = x => Math.round(x * 100) / 100;
const cap = resp.body || {};
const fehlerText = r => [
  r.body?.name,
  r.body?.message,
  ...(r.body?.details || []).map(d => [d.issue, d.description].filter(Boolean).join(': ')),
  r.body?.debug_id ? 'debug_id ' + r.body.debug_id : '',
  r.error?.message
].filter(Boolean).join(' | ').slice(0, 400);

const info = {
  transaktionsId: src.captureId,
  zahlungsdatum: cap.create_time || src.zahlungsdatum,
  zahlungsBetrag: src.zahlungsBetrag,
  captureStatus: cap.status || '',
  zuordnung: src.zuordnung,
  debug: `${src.debug} · GET capture ${resp.statusCode ? 'HTTP ' + resp.statusCode : 'keine Antwort'}${cap.status ? ' ' + cap.status : ''}`
};
const vermerk = (status, grund, extra = {}) => sd.done.push({
  bestellnummer: src.bestellnummer, status, grund: String(grund).slice(0, 500), ...info, ...extra, bearbeitetAm: new Date().toISOString()
});
const weiter = (weg, extra = {}) => [{ json: { ...src, ...info, weg, ...extra } }];

if (resp.statusCode === 404) {
  vermerk('CAPTURE_NICHT_GEFUNDEN', 'PayPal findet die Zahlung nicht über die Payments API: ' + fehlerText(resp));
  return weiter('KEINER');
}
if (resp.statusCode !== 200) {
  vermerk('FEHLER', `Zahlung abrufen: ${resp.statusCode ? 'HTTP ' + resp.statusCode : 'keine Antwort'} ${fehlerText(resp)}`);
  return weiter('KEINER');
}

// Capture-Status laut PayPal: COMPLETED, DECLINED, PARTIALLY_REFUNDED, PENDING, REFUNDED, FAILED
if (cap.status === 'REFUNDED') {
  vermerk('BEREITS_ERSTATTET', 'Zahlung ist bei PayPal bereits vollständig erstattet');
  return weiter('KEINER');
}
if (cap.status === 'PARTIALLY_REFUNDED') {
  vermerk('BEREITS_TEILERSTATTET', 'Zahlung ist bei PayPal bereits teilweise erstattet – manuell prüfen');
  return weiter('KEINER');
}
if (cap.status !== 'COMPLETED') {
  vermerk('ZAHLUNG_PRUEFEN', `Zahlungsstatus ${cap.status}${cap.status_details?.reason ? ' (' + cap.status_details.reason + ')' : ''}`);
  return weiter('KEINER');
}

const gezahlt = Number(cap.amount?.value);
const waehrung = cap.amount?.currency_code;
// ALLES: die ganze PayPal-Zahlung, sonst der berechnete Betrag
const betrag = src.aktion === 'ALLES' ? gezahlt : runden(src.erstattungsbetrag);
if (!(betrag > 0) || betrag > gezahlt) {
  vermerk('ZAHLUNG_PRUEFEN', `Erstattung ${Number(betrag).toFixed(2)} passt nicht zur PayPal-Zahlung ${gezahlt.toFixed(2)}`);
  return weiter('KEINER');
}

const alterTage = Math.floor((Date.now() - new Date(info.zahlungsdatum)) / 86400000);
if (Number.isNaN(alterTage)) {
  vermerk('ZAHLUNG_PRUEFEN', 'Zahlungsdatum fehlt');
  return weiter('KEINER');
}
const innerhalbFrist = alterTage <= config.erstattungsfristTage;

if (!innerhalbFrist && !config.payoutsAktiv) {
  vermerk('FRIST_ABGELAUFEN', `Zahlung ${alterTage} Tage alt – PayPal erstattet nur innerhalb von ${config.erstattungsfristTage} Tagen. Payouts nicht aktiv: ${betrag.toFixed(2)} ${waehrung} manuell erstatten`, { betrag });
  return weiter('KEINER');
}
if (!innerhalbFrist && !src.email) {
  vermerk('ZAHLUNG_PRUEFEN', 'Payout nicht möglich: keine PayPal-E-Mail des Zahlers', { betrag });
  return weiter('KEINER');
}

const weg = innerhalbFrist ? 'ERSTATTUNG' : 'PAYOUT';
// Eindeutig je Bestellung und Buch – schützt vor doppelter Erstattung/Auszahlung bei Wiederholung
const vorgang = `produktentfernung-wc-${src.bestellnummer}-${src.skus.join('+')}`;

// Jede Erstattung und jeder Payout steht im Protokoll (Data Table). Bearbeitet wird nur, wenn der Vorgang
// dort noch nicht steht oder der letzte Versuch ABGELEHNT war (kein Geld geflossen).
// Alle anderen Status (RESERVIERT, UNKLAR, DUPLIKAT, PENDING, COMPLETED …) sperren.
const protokoll = $('Protokoll laden').all().map(i => i.json);
const lesefehler = protokoll.find(r => r.error);
if (lesefehler) {
  vermerk('ZAHLUNG_PRUEFEN', 'Protokoll nicht lesbar – keine Erstattung ohne Doppelschutz: ' + JSON.stringify(lesefehler.error).slice(0, 200), { betrag, weg });
  return weiter('KEINER');
}
const eintrag = protokoll.find(r => r.vorgang === vorgang);
if (eintrag && eintrag.status !== 'ABGELEHNT') {
  const offen = ['RESERVIERT', 'UNKLAR'].includes(eintrag.status) ? ' – Ergebnis beim Zahlungsanbieter prüfen' : '';
  vermerk(eintrag.weg === 'PAYOUT' ? 'BEREITS_AUSGEZAHLT' : 'BEREITS_ERSTATTET',
    `Laut Protokoll: ${eintrag.weg || ''} ${eintrag.status} seit ${String(eintrag.createdAt).slice(0, 10)}${eintrag.referenz ? ', Referenz ' + eintrag.referenz : ''}${offen}`,
    { betrag, weg: eintrag.weg || weg, referenz: eintrag.referenz || '' });
  return weiter('KEINER');
}

if (config.modus !== 'SCHARF') {
  vermerk('TROCKENLAUF', weg === 'ERSTATTUNG'
    ? `würde ${betrag.toFixed(2)} ${waehrung} erstatten (Zahlung ${alterTage} Tage alt)`
    : `würde ${betrag.toFixed(2)} ${waehrung} per Payout an ${src.email} senden (Zahlung ${alterTage} Tage alt)`,
  { betrag, weg });
  return weiter('KEINER');
}

// Test-Limit: im Modus SCHARF nur die ersten Config.testLimit Erstattungen/Payouts über PayPal, der Rest wird nur geprüft
const limit = Number(config.testLimit) || 0;
sd.lauf = sd.lauf || {};
if (limit > 0 && (sd.lauf.testPayPal || 0) >= limit) {
  vermerk('NICHT_VERARBEITET', `Test-Limit (${limit}) erreicht – würde ${betrag.toFixed(2)} ${waehrung} ${weg === 'ERSTATTUNG' ? 'erstatten' : 'per Payout senden'} (Zahlung ${alterTage} Tage alt)`, { betrag, weg });
  return weiter('KEINER');
}
sd.lauf.testPayPal = (sd.lauf.testPayPal || 0) + 1;

// Für "Protokoll: reservieren" und die Erstattung bzw. den Payout
const protokollFelder = { vorgang, betrag, waehrung, transaktionsId: src.captureId };

if (weg === 'ERSTATTUNG') {
  const body = {
    note_to_payer: String(config.notizAnKunde).slice(0, 255),
    custom_id: String(src.bestellnummer).slice(0, 127)
  };
  // Ohne amount erstattet PayPal "captured amount - previous refunds", also die ganze Zahlung
  if (src.aktion !== 'ALLES') body.amount = { value: betrag.toFixed(2), currency_code: waehrung };
  return weiter('ERSTATTUNG', { ...protokollFelder, refundBody: JSON.stringify(body) });
}

// Payout: neue Zahlung an die PayPal-E-Mail des Zahlers.
// sender_batch_id und PayPal-Request-Id schützen 30 Tage vor Doppelzahlung, danach das Protokoll.
const body = {
  sender_batch_header: {
    sender_batch_id: vorgang,
    recipient_type: 'EMAIL',
    email_subject: config.payoutBetreff,
    email_message: config.payoutNachricht
  },
  items: [{
    recipient_type: 'EMAIL',
    amount: { value: betrag.toFixed(2), currency: waehrung },
    receiver: src.email,
    note: `${config.notizAnKunde} Bestellung ${src.bestellnummer}`,
    sender_item_id: String(src.bestellnummer).slice(0, 63)
  }]
};
return weiter('PAYOUT', { ...protokollFelder, payoutBody: JSON.stringify(body) });

// Wertet die PayPal-Erstattung aus und bereitet den Protokoll-Eintrag vor.
// Bewusst kein throw: der Loop geht weiter, der Report zeigt den Fehler.
const resp = $input.first().json;
const src = $('Zahlung prüfen + Weg wählen').first().json;
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.done)) sd.done = [];

const r = resp.body || {};
const fehlerText = x => [
  x.body?.name,
  x.body?.message,
  ...(x.body?.details || []).map(d => [d.issue, d.description].filter(Boolean).join(': ')),
  x.body?.debug_id ? 'debug_id ' + x.body.debug_id : '',
  x.error?.message
].filter(Boolean).join(' | ').slice(0, 400);
const antwort = resp.statusCode ? 'HTTP ' + resp.statusCode : 'keine Antwort';

// 201 = Erstattung angelegt, 200 = Antwort auf eine schon gestellte Anfrage mit derselben PayPal-Request-Id
// Refund-Status laut PayPal: CANCELLED, FAILED, PENDING, COMPLETED
let status;
let protokollStatus;
let grund = '';
if ([200, 201].includes(resp.statusCode) && r.id) {
  status = { COMPLETED: 'ERSTATTET', PENDING: 'ERSTATTUNG_AUSSTEHEND' }[r.status] || 'FEHLER';
  // FAILED/CANCELLED: kein Geld geflossen -> neuer Versuch erlaubt
  protokollStatus = status === 'FEHLER' ? 'ABGELEHNT' : r.status;
  if (status !== 'ERSTATTET') {
    grund = `PayPal-Status ${r.status}${r.status_details?.reason ? ' (' + r.status_details.reason + ')' : ''}`;
  }
  if (resp.statusCode === 200) {
    grund = [grund, 'Erstattung bestand bereits (gleiche PayPal-Request-Id)'].filter(Boolean).join(' · ');
  }
} else if (resp.statusCode >= 400 && resp.statusCode < 500) {
  // Abgelehnt, kein Geld geflossen
  status = 'FEHLER';
  protokollStatus = 'ABGELEHNT';
  grund = `Erstattung: ${antwort} ${fehlerText(resp)}`;
} else {
  // 5xx oder keine Antwort: offen, ob PayPal erstattet hat -> UNKLAR sperrt weitere Versuche
  status = 'FEHLER';
  protokollStatus = 'UNKLAR';
  grund = `Erstattung: ${antwort} ${fehlerText(resp)} – Ergebnis unklar, in PayPal prüfen`;
}

const erstattet = r.amount?.value !== undefined ? Number(r.amount.value) : null;
if (status !== 'FEHLER' && erstattet !== null && Math.abs(erstattet - src.betrag) > 0.01) {
  grund = [grund, `Erstattet ${erstattet.toFixed(2)}, erwartet ${src.betrag.toFixed(2)} – prüfen`].filter(Boolean).join(' · ');
}

sd.done.push({
  bestellnummer: src.bestellnummer,
  status,
  grund: grund.slice(0, 500),
  weg: 'ERSTATTUNG',
  transaktionsId: src.transaktionsId,
  zahlungsdatum: src.zahlungsdatum,
  zahlungsBetrag: src.zahlungsBetrag,
  captureStatus: src.captureStatus,
  zuordnung: src.zuordnung,
  betrag: erstattet ?? src.betrag,
  referenz: r.id || '',
  anbieterStatus: r.status || '',
  debug: `${src.debug} · Refund ${antwort}${r.status ? ' ' + r.status : ''}${r.debug_id || resp.body?.debug_id ? ' · debug_id ' + (r.debug_id || resp.body.debug_id) : ''}`,
  bearbeitetAm: new Date().toISOString()
});

// Für "Protokoll: Ergebnis" (Data Table)
return [{
  json: {
    vorgang: src.vorgang,
    bestellnummer: src.bestellnummer,
    weg: 'ERSTATTUNG',
    transaktionsId: src.transaktionsId,
    betrag: erstattet ?? src.betrag,
    waehrung: src.waehrung,
    protokollStatus,
    referenz: r.id || '',
    protokollGrund: (grund || status).slice(0, 250)
  }
}];

// Wertet den Payout aus und bereitet den Protokoll-Eintrag vor.
// PayPal bearbeitet Payouts asynchron: PENDING heißt angenommen, nicht ausgezahlt.
const resp = $input.first().json;
const src = $('Zahlung prüfen + Weg wählen').first().json;
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.done)) sd.done = [];

const body = resp.body || {};
const kopf = body.batch_header || {};
const fehlerText = x => [
  x.body?.name,
  x.body?.message,
  ...(x.body?.details || []).map(d => [d.field, d.issue, d.description].filter(Boolean).join(': ')),
  x.body?.debug_id ? 'debug_id ' + x.body.debug_id : '',
  x.error?.message
].filter(Boolean).join(' | ').slice(0, 400);

const antwort = resp.statusCode ? 'HTTP ' + resp.statusCode : 'keine Antwort';

// Batch-Status laut PayPal: DENIED, PENDING, PROCESSING, SUCCESS, CANCELED
const angelegt = resp.statusCode === 201 && Boolean(kopf.payout_batch_id);
const ok = angelegt && kopf.batch_status !== 'DENIED';
// sender_batch_id in den letzten 30 Tagen schon verwendet: PayPal lehnt ab und verlinkt den ursprünglichen Payout
const duplikat = !angelegt && (
  (body.links || []).some(l => /\/v1\/payments\/payouts\//.test(String(l.href))) ||
  /duplicate/i.test(`${body.name} ${body.message}`)
);
// 4xx bzw. DENIED = abgelehnt, kein Geld geflossen -> neuer Versuch erlaubt.
// 5xx oder keine Antwort: offen, ob PayPal ausgezahlt hat -> UNKLAR sperrt weitere Versuche.
const abgelehnt = !ok && !duplikat && ((angelegt && kopf.batch_status === 'DENIED') || (resp.statusCode >= 400 && resp.statusCode < 500));

let status;
let protokollStatus;
let grund;
if (ok) {
  status = 'AUSZAHLUNG_ANGESTOSSEN';
  protokollStatus = kopf.batch_status || 'PENDING';
  grund = `Payout-Status ${kopf.batch_status} – Abschluss in PayPal prüfen`;
} else if (duplikat) {
  status = 'BEREITS_AUSGEZAHLT';
  protokollStatus = 'DUPLIKAT';
  grund = 'PayPal: Payout mit derselben sender_batch_id existiert bereits – ' + fehlerText(resp);
} else if (abgelehnt) {
  status = 'FEHLER';
  protokollStatus = 'ABGELEHNT';
  grund = angelegt ? `Payout von PayPal abgelehnt (Status DENIED, ${kopf.payout_batch_id})` : `Payout: ${antwort} ${fehlerText(resp)}`;
} else {
  status = 'FEHLER';
  protokollStatus = 'UNKLAR';
  grund = `Payout: ${antwort} ${fehlerText(resp)} – Ergebnis unklar, in PayPal prüfen`;
}

sd.done.push({
  bestellnummer: src.bestellnummer,
  status,
  grund: grund.slice(0, 500),
  weg: 'PAYOUT',
  transaktionsId: src.transaktionsId,
  zahlungsdatum: src.zahlungsdatum,
  zahlungsBetrag: src.zahlungsBetrag,
  captureStatus: src.captureStatus,
  zuordnung: src.zuordnung,
  betrag: src.betrag,
  empfaenger: src.email,
  referenz: kopf.payout_batch_id || '',
  anbieterStatus: kopf.batch_status || '',
  debug: `${src.debug} · Payout ${antwort}${kopf.batch_status ? ' ' + kopf.batch_status : ''}${body.debug_id ? ' · debug_id ' + body.debug_id : ''}`,
  bearbeitetAm: new Date().toISOString()
});

// Für "Protokoll: Ergebnis" (Data Table)
return [{
  json: {
    vorgang: src.vorgang,
    bestellnummer: src.bestellnummer,
    weg: 'PAYOUT',
    transaktionsId: src.transaktionsId,
    betrag: src.betrag,
    waehrung: src.waehrung,
    protokollStatus,
    referenz: kopf.payout_batch_id || '',
    protokollGrund: grund.slice(0, 250)
  }
}];

// Abschluss-Report: genau eine Zeile je Bestellung aus dem Export, bearbeitete zuerst
const config = $('Config').first().json.config;
const sd = $getWorkflowStaticData('global');
const gefunden = sd.toFix || [];
const erledigt = sd.done || [];
const skipped = sd.skipped || [];

// Alle Zeilen mit denselben Spalten, sonst wird die CSV uneinheitlich
const LEER = {
  positionen: '', versandpositionen: '', zahlungsart: '', zahlungsweg: '', transaktionsIdExport: '', zuordnung: '', debug: '',
  bestellnummer: '', status: '', fall: '', weg: '', grund: '', bestelldatum: '', skus: '', menge: '',
  weiterePositionen: '', sonstigePositionen: '', land: '', versandart: '', versandkosten: '', versandErstattung: '',
  buchWert: '', bestellwert: '', erstattungsbetrag: '', transaktionsId: '', zahlungsdatum: '', zahlungsBetrag: '',
  captureStatus: '', betrag: '', empfaenger: '', referenz: '', anbieterStatus: '', waehrung: '', bearbeitetAm: ''
};

// Beträge im Text deutsch formatiert, z. B. 19,90
const eur = x => Number(x).toFixed(2).replace('.', ',');
const posText = p => `${p.title}${p.sku ? ' [' + p.sku + ']' : ''}: `
  + (p.menge > 1 ? `${p.menge} × ${eur(p.brutto / p.menge)} = ${eur(p.brutto)}` : eur(p.brutto));

const zeile = (o, extra) => ({
  ...LEER,
  bestellnummer: o.bestellnummer,
  fall: o.fall || '',
  bestelldatum: o.bestelldatum || '',
  skus: (o.positionen || []).map(p => p.sku + (p.ohneArtikelnummer ? ' (per Bezeichnung)' : '')).join(' | '),
  positionen: (o.positionenAlle || []).map(posText).join(' | '),
  versandpositionen: (o.versandZeilen || []).map(p => `${p.title}: ${eur(p.brutto)}`).join(' | '),
  menge: (o.positionen || []).reduce((s, p) => s + Number(p.menge || 0), 0),
  weiterePositionen: (o.weitere || []).map(p => `${p.sku || p.title} ×${p.menge}`).join(' | '),
  sonstigePositionen: (o.sonstige || []).map(p => `${p.title || '?'} ${p.brutto}`).join(' | '),
  land: o.land || '',
  versandart: o.versandart || '',
  versandkosten: o.versandkosten ?? '',
  versandErstattung: o.versandErstattung ?? '',
  buchWert: o.buchWert ?? '',
  bestellwert: o.bestellwert ?? '',
  erstattungsbetrag: o.erstattungsbetrag ?? '',
  waehrung: o.waehrung || '',
  zahlungsart: o.zahlungsart || '',
  zahlungsweg: o.zahlungsweg || '',
  transaktionsIdExport: o.transaktionsIdExport || '',
  ...extra
});

const anbieter = o => ({ PAYPAL: 'PayPal', MOLLIE: 'Mollie' }[o.zahlungsweg] || 'Zahlungsanbieter');
const vorhaben = o => o.aktion === 'ALLES'
  ? `ganze ${anbieter(o)}-Zahlung (laut Export ${o.bestellwert.toFixed(2)}) – ${anbieter(o)} nicht abgefragt`
  : `${o.erstattungsbetrag.toFixed(2)} (Buch ${o.buchWert.toFixed(2)}`
    + (o.versandErstattung > 0 ? ` + Versand ${o.versandErstattung.toFixed(2)})` : ', ohne Versand)')
    + ` – ${anbieter(o)} nicht abgefragt`;

const rows = [];
for (const o of gefunden) {
  const d = erledigt.find(e => e.bestellnummer === o.bestellnummer);
  if (config.modus === 'NUR_EINORDNEN') {
    rows.push(zeile(o, { status: 'EINGEORDNET', grund: vorhaben(o) }));
  } else if (!d) {
    rows.push(zeile(o, { status: 'NICHT_VERARBEITET', grund: `Lauf abgebrochen – Bestellung in der ${anbieter(o)}-Schleife nicht erreicht` }));
  } else {
    const { bestellnummer, ...ergebnis } = d;
    rows.push(zeile(o, ergebnis));
  }
}

for (const s of skipped) {
  rows.push(zeile(s, { status: s.status, grund: s.grund }));
}

return rows.map(r => ({ json: r }));

// Report-CSV: Spalten in der Reihenfolge der Auswertung, mit deutschen Überschriften.
// Die Report-Mail liest weiter direkt aus "Report erstellen".
const WEG = { ERSTATTUNG: 'PayPal-Erstattung', PAYOUT: 'PayPal-Payout', MOLLIE: 'Mollie-Erstattung' };
// Nur bei diesen Status wurde tatsächlich Geld angewiesen (sonst steht in betrag nur der geplante Betrag)
const ANGEWIESEN = ['ERSTATTET', 'ERSTATTUNG_AUSSTEHEND', 'AUSZAHLUNG_ANGESTOSSEN'];
// Bei diesen Status muss jemand von Hand erstatten
const MANUELL = ['FRIST_ABGELAUFEN', 'MANUELL_ERSTATTEN', 'ZAHLUNGSART_UNBEKANNT', 'EINZELVERSAND_WEITERE_ARTIKEL', 'GUTSCHEIN'];

return $input.all().map(({ json: r }) => ({
  json: {
    'Bestellnummer': r.bestellnummer,
    'Status': r.status,
    'Fall': r.fall,
    'Positionen': r.positionen,
    'Gesamtpreis': r.bestellwert,
    'Positionspreis Buch': r.buchWert,
    'Versandpositionen': r.versandpositionen,
    'Erstattungswert': r.erstattungsbetrag,
    'Erstattet': ANGEWIESEN.includes(r.status) ? r.betrag : '',
    'Erstattungsweg': MANUELL.includes(r.status) ? 'manuell' : (WEG[r.weg] || r.weg || ''),
    'Datum der Erstattung': ANGEWIESEN.includes(r.status) ? String(r.bearbeitetAm).slice(0, 16).replace('T', ' ') : '',
    'Transaktionsnummer': r.transaktionsId || r.transaktionsIdExport,
    'Erstattungs-/Payout-ID': r.referenz,
    'Grund': r.grund,
    'Zahlungsart (Export)': r.zahlungsart,
    'Zahlungsweg': { PAYPAL: 'PayPal', MOLLIE: 'Mollie' }[r.zahlungsweg] || '',
    'Bestelldatum': r.bestelldatum,
    'Versandart': r.versandart,
    'Versandkosten': r.versandkosten,
    'Versanderstattung': r.versandErstattung,
    'Land': r.land,
    'Währung': r.waehrung,
    'Gezahlt (Anbieter)': r.zahlungsBetrag,
    'Zahlungsdatum': String(r.zahlungsdatum || '').slice(0, 10),
    'Zahlungsstatus (Anbieter)': r.captureStatus,
    'Erstattungsstatus (Anbieter)': r.anbieterStatus,
    'Empfänger (Payout)': r.empfaenger,
    'Debug': r.debug
  }
}));

// Übersicht des Erstattungs-Protokolls (Data Table) und Lauf-Info für die Report-Mail – Monitoring und Debugging bei jedem Lauf.
// Die Report-CSV (Binary) wird unverändert durchgereicht.
const config = $('Config').first().json.config;
const sd = $getWorkflowStaticData('global');
const lauf = sd.lauf || {};
const eintraege = $('Protokoll für Report laden').all().map(i => i.json);
const lesefehler = eintraege.find(r => r.error);
const rows = eintraege.filter(r => r.vorgang);
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const WEG = { ERSTATTUNG: 'PayPal-Erstattung', PAYOUT: 'PayPal-Payout', MOLLIE: 'Mollie-Erstattung' };

// Lauf-Info: was der Flow bei den Anbietern abgefragt und wie er zugeordnet hat
const info = [];
if (config.modus === 'NUR_EINORDNEN') {
  info.push('PayPal und Mollie nicht abgefragt (NUR_EINORDNEN)');
} else {
  info.push(lauf.paypalZahlungen === undefined
    ? 'PayPal: nicht abgefragt'
    : `PayPal-Suche: ${lauf.paypalBestellungen ?? '?'} Bestellung(en) mit ${lauf.paypalBetraege ?? '?'} verschiedenen Beträgen, `
      + `${lauf.paypalSuchen ?? '?'} Suche(n), ${lauf.paypalSeiten} Seite(n), ${lauf.paypalZahlungen} eingehende Zahlungen · Zuordnung: `
      + (Object.entries(lauf.paypalZuordnung || {}).map(([k, n]) => `${esc(k)} ${n}`).join(', ') || '–')
      + ` · davon über Mollie bezahlt (weiter an Mollie): ${lauf.paypalMitMollieId ?? 0}`);
  info.push(`Mollie: ${lauf.mollieBestellungen ?? 0} Bestellung(en), davon ${lauf.mollieAusPayPal ?? 0} mit Mollie-ID aus PayPal, ${lauf.mollieVonPayPal ?? 0} von PayPal nicht gefunden · ${(lauf.mollieDirekt ?? 0) - (lauf.mollieAusPayPal ?? 0)} mit ID aus dem Export`
    + (lauf.mollieSuche ? ` · Suche: ${lauf.mollieZahlungenGeladen ?? 0} Zahlungen und ${lauf.mollieOrdersGeladen ?? 0} Orders geladen` : '')
    + (lauf.mollieNichtGesucht ? ` · <b>Suche abgeschaltet:</b> ${lauf.mollieNichtGesucht} Bestellung(en) ohne Mollie-ID nicht gesucht` : '')
    + ` · Zuordnung: ${Object.entries(lauf.mollieZuordnung || {}).map(([k, n]) => `${esc(k)} ${n}`).join(', ') || '–'}`
    + (lauf.mollieLadefehler ? ` · <b>Ladefehler:</b> ${esc(lauf.mollieLadefehler)}` : ''));
}
if ((config.nurBestellungen || []).length) info.push(`Nur Bestellungen: ${esc(config.nurBestellungen.join(', '))}`);
if (config.modus === 'SCHARF' && Number(config.testLimit) > 0) info.push(`Test-Limit: ${config.testLimit} je Zahlungsweg`);
let html = `<p><b>Lauf-Info:</b> ${info.join(' · ')}</p>`;

if (lesefehler) {
  html += `<p><b>Erstattungs-Protokoll nicht lesbar:</b> ${esc(JSON.stringify(lesefehler.error).slice(0, 300))}</p>`;
} else if (!rows.length) {
  html += '<p>Erstattungs-Protokoll: noch keine Einträge.</p>';
} else {
  const nachStatus = {};
  for (const r of rows) nachStatus[r.status] = (nachStatus[r.status] || 0) + 1;
  // ABGELEHNT = kein Geld geflossen
  const summe = rows.filter(r => r.status !== 'ABGELEHNT').reduce((s, r) => s + Number(r.betrag || 0), 0);
  const offen = rows.filter(r => ['RESERVIERT', 'UNKLAR'].includes(r.status));
  html += '<h4>Erstattungs-Protokoll (alle Läufe)</h4>'
    + `<p>${rows.length} Einträge · ${Object.entries(nachStatus).map(([s, n]) => `${esc(s)}: ${n}`).join(' · ')} · Summe ohne ABGELEHNT: ${summe.toFixed(2)}</p>`
    + (offen.length ? `<p><b>Achtung:</b> ${offen.length} Einträge mit Status RESERVIERT/UNKLAR – Ergebnis beim Zahlungsanbieter prüfen.</p>` : '')
    + '<table border="1" cellpadding="4" cellspacing="0"><tr><th>Angelegt</th><th>Bestellung</th><th>Weg</th><th>Betrag</th><th>Status</th><th>Referenz</th><th>Grund</th></tr>'
    + rows.map(r => '<tr>'
      + `<td>${esc(String(r.createdAt).slice(0, 16).replace('T', ' '))}</td>`
      + `<td>${esc(r.bestellnummer)}</td>`
      + `<td>${esc(WEG[r.weg] || r.weg)}</td>`
      + `<td>${Number(r.betrag || 0).toFixed(2)} ${esc(r.waehrung)}</td>`
      + `<td>${esc(r.status)}</td>`
      + `<td>${esc(r.referenz)}</td>`
      + `<td>${esc(r.grund)}</td>`
      + '</tr>').join('')
    + '</table><p>Status = Stand bei der Erstattung bzw. beim Payout, den Abschluss zeigt der Zahlungsanbieter. Die Tabelle liegt in n8n unter „Data tables“.</p>';
}

return [{ json: { protokollHtml: html }, binary: $input.first().binary }];

// Mollie-Teil vorbereiten (läuft nach PayPal): Bestellungen mit Zahlungsweg Mollie, alle, die PayPal nicht gefunden hat,
// und PayPal-Zahlungen über Mollie (Mollie-ID aus dem PayPal-Feld custom_field).
// Mit Mollie-ID (Export oder PayPal) direkt, sonst über die Mollie-Suche (Zahlungen und Orders laden, Bestellnummer zuordnen).
const config = $('Config').first().json.config;
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.done)) sd.done = [];
sd.lauf = sd.lauf || {};
sd.mollieDirekt = [];
sd.mollieSuche = [];

if (config.modus === 'NUR_EINORDNEN') return [{ json: { suche: 0 } }];

// Von PayPal nicht gefunden: was dort gesucht wurde, steht später im Grund, falls Mollie auch nichts findet
const nichtBeiPayPal = new Map((sd.paypalNichtGefunden || []).map(x => [x.bestellnummer, x.gesucht]));
// Bei PayPal gefunden, über Mollie bezahlt
const ausPayPal = new Map((sd.paypalMollie || []).map(x => [x.bestellnummer, x]));
const kandidaten = (sd.toFix || []).filter(o => o.zahlungsweg === 'MOLLIE' || nichtBeiPayPal.has(o.bestellnummer) || ausPayPal.has(o.bestellnummer));

for (const o of kandidaten) {
  const id = String(o.transaktionsIdExport || '').trim();
  const eintrag = {
    bestellnummer: o.bestellnummer,
    aktion: o.aktion,
    fall: o.fall,
    skus: o.skus,
    waehrung: o.waehrung,
    bestellwert: o.bestellwert,
    bestelldatum: o.bestelldatum,
    erstattungsbetrag: o.erstattungsbetrag,
    paypalGesucht: nichtBeiPayPal.get(o.bestellnummer) || ''
  };
  const pp = ausPayPal.get(o.bestellnummer);
  if (/^(tr|ord)_\w+$/.test(id)) sd.mollieDirekt.push({ ...eintrag, mollieId: id, zuordnung: 'Transaktions-ID' });
  else if (pp) {
    sd.mollieDirekt.push({
      ...eintrag,
      mollieId: pp.mollieId,
      zuordnung: 'PayPal-Rechnungsnummer → Mollie-ID',
      paypalTransaktionsId: pp.paypalTransaktionsId,
      paypalEmail: pp.paypalEmail,
      debug: pp.debug
    });
  }
  else sd.mollieSuche.push(eintrag);
}

// Mollie-Suche abgeschaltet: Bestellungen ohne Mollie-ID werden nicht gesucht, sondern für die manuelle Bearbeitung markiert
const nichtGesucht = config.mollieSucheAktiv === false ? sd.mollieSuche.splice(0) : [];
for (const o of nichtGesucht) {
  sd.done.push({
    bestellnummer: o.bestellnummer,
    status: 'NICHT_GEFUNDEN',
    grund: (o.paypalGesucht ? `Bei PayPal nicht gefunden (${o.paypalGesucht}). ` : 'Keine Mollie-ID. ')
      + 'Mollie-Suche abgeschaltet (Config mollieSucheAktiv) – manuell bearbeiten, z. B. im Mollie-Dashboard über die Bestellnummer suchen',
    zuordnung: 'nicht gesucht',
    bearbeitetAm: new Date().toISOString()
  });
}

// Suchzeitraum: ab dem Vortag der ältesten gesuchten Bestellung (Mollie liefert die neuesten Zahlungen zuerst)
const TAG = 86400000;
const ab = sd.mollieSuche.length
  ? new Date(Math.min(...sd.mollieSuche.map(o => new Date(o.bestelldatum).getTime())) - TAG).toISOString()
  : '';

sd.lauf.mollieBestellungen = kandidaten.length;
sd.lauf.mollieVonPayPal = kandidaten.filter(o => nichtBeiPayPal.has(o.bestellnummer)).length;
sd.lauf.mollieAusPayPal = kandidaten.filter(o => ausPayPal.has(o.bestellnummer)).length;
sd.lauf.mollieDirekt = sd.mollieDirekt.length;
sd.lauf.mollieSuche = sd.mollieSuche.length;
sd.lauf.mollieNichtGesucht = nichtGesucht.length;

// Steuer-Item: suche > 0 -> Mollie-Zahlungen und -Orders laden, sonst direkt zur Zuordnung
return [{ json: { suche: sd.mollieSuche.length, ab } }];

// Prüft die Zahlung bei Mollie und wählt den Weg: MOLLIE (Erstattung über die API), PAYOUT (PayPal über Mollie, älter als
// die Mollie-Frist: Payout bei PayPal an die PayPal-E-Mail des Zahlers) oder KEINER (Report-Eintrag, keine Aktion).
// Erstattbar ist eine Zahlung nur, solange Mollie amountRemaining (erstattbarer Restbetrag) liefert und die Frist der Zahlart läuft.
const resp = $input.first().json;
const src = $('Loop Mollie').first().json;
const config = $('Config').first().json.config;
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.done)) sd.done = [];

const runden = x => Math.round(x * 100) / 100;
// Mollie antwortet mit Content-Type application/hal+json – je nach n8n-Einstellung kommt der Body als Text an
const alsObjekt = b => {
  if (b && typeof b === 'object') return b;
  if (typeof b !== 'string' || !b.trim()) return {};
  try { return JSON.parse(b); } catch (e) { return { parseFehler: 'Antwort nicht lesbar: ' + b.slice(0, 150) }; }
};
const body = alsObjekt(resp.body);
const fehlerText = r => {
  const b = alsObjekt(r.body);
  return [b.title, b.detail, b.field ? 'Feld ' + b.field : '', b.parseFehler, r.error?.message].filter(Boolean).join(' | ').slice(0, 400);
};
const antwort = resp.statusCode ? 'HTTP ' + resp.statusCode : 'keine Antwort';

// Mollie-Order (ord_): die bezahlte Zahlung aus _embedded.payments, sonst die Zahlung selbst
const zahlungen = body.resource === 'order' ? (body._embedded?.payments || []) : [body];
const zahlung = zahlungen.find(p => p.status === 'paid') || zahlungen[0] || {};

const info = {
  transaktionsId: zahlung.id || src.mollieId,
  zahlungsdatum: zahlung.paidAt || zahlung.createdAt || '',
  zahlungsBetrag: zahlung.amount ? Number(zahlung.amount.value) : '',
  captureStatus: zahlung.status || '',
  zuordnung: src.zuordnung || 'Transaktions-ID',
  debug: `${src.debug ? src.debug + ' · ' : ''}Mollie GET ${src.mollieId} ${antwort}${zahlung.status ? ' ' + zahlung.status : ''}${zahlung.method ? ' · Zahlart ' + zahlung.method : ''}`
    + (zahlung.amountRemaining ? ` · erstattbar ${zahlung.amountRemaining.value}` : '')
};
const vermerk = (status, grund, extra = {}) => sd.done.push({
  bestellnummer: src.bestellnummer, status, grund: String(grund).slice(0, 500), ...info, ...extra, bearbeitetAm: new Date().toISOString()
});
const weiter = (weg, extra = {}) => [{ json: { ...src, ...info, weg, ...extra } }];

if (resp.statusCode === 404) {
  vermerk('NICHT_GEFUNDEN', `Mollie kennt die Transaktions-ID ${src.mollieId} nicht: ${fehlerText(resp)}`
    + (src.paypalTransaktionsId ? ` – Mollie-ID aus der PayPal-Zahlung ${src.paypalTransaktionsId}; gehört der API-Key zum Website-Profil des WooCommerce-Shops?` : ''));
  return weiter('KEINER');
}
if (resp.statusCode !== 200 || body.parseFehler) {
  vermerk('FEHLER', `Mollie abrufen: ${antwort} ${fehlerText(resp)}`);
  return weiter('KEINER');
}
if (!zahlung.id) {
  vermerk('ZAHLUNG_PRUEFEN', `Mollie-Order ${src.mollieId} ohne Zahlung`);
  return weiter('KEINER');
}

// Zahlungsstatus laut Mollie: open, pending, authorized, paid, canceled, expired, failed
if (zahlung.status !== 'paid') {
  vermerk('ZAHLUNG_PRUEFEN', `Mollie-Status ${zahlung.status}`);
  return weiter('KEINER');
}
const gezahlt = Number(zahlung.amount?.value);
const waehrung = zahlung.amount?.currency;
if (waehrung !== src.waehrung) {
  vermerk('ZAHLUNG_PRUEFEN', `Währung bei Mollie ${waehrung}, im Export ${src.waehrung}`);
  return weiter('KEINER');
}
// Gegenprobe wie bei PayPal: Mollie-Betrag = Bestellwert laut Export
if (Math.abs(gezahlt - src.bestellwert) > 0.01) {
  vermerk('BETRAG_PRUEFEN', `Mollie-Zahlung ${gezahlt.toFixed(2)}, Bestellwert laut Export ${Number(src.bestellwert).toFixed(2)}`);
  return weiter('KEINER');
}
const schonErstattet = Number(zahlung.amountRefunded?.value || 0);
if (schonErstattet > 0) {
  vermerk(schonErstattet >= gezahlt - 0.005 ? 'BEREITS_ERSTATTET' : 'BEREITS_TEILERSTATTET',
    `Mollie: bereits ${schonErstattet.toFixed(2)} ${waehrung} erstattet${schonErstattet >= gezahlt - 0.005 ? '' : ' – manuell prüfen'}`);
  return weiter('KEINER');
}

// ALLES: die ganze Zahlung, sonst der berechnete Betrag
const betrag = src.aktion === 'ALLES' ? gezahlt : runden(src.erstattungsbetrag);
if (!(betrag > 0) || betrag > gezahlt) {
  vermerk('ZAHLUNG_PRUEFEN', `Erstattung ${Number(betrag).toFixed(2)} passt nicht zur Mollie-Zahlung ${gezahlt.toFixed(2)}`);
  return weiter('KEINER');
}

const alterTage = Math.floor((Date.now() - new Date(info.zahlungsdatum)) / 86400000);
const frist = (config.mollieFristTage || {})[zahlung.method];
const fristAbgelaufen = Boolean(frist && alterTage > frist);
// Ohne amountRemaining bietet Mollie für diese Zahlung keine Erstattung (mehr) an
const rest = zahlung.amountRemaining ? Number(zahlung.amountRemaining.value) : null;

// PayPal über Mollie: Mollie erstattet nur bis zur Frist (180 Tage). Danach – oder wenn Mollie keine Erstattung mehr
// anbietet – Payout bei PayPal an die PayPal-E-Mail des Zahlers (laut Mollie, sonst laut PayPal-Suche).
let weg = 'MOLLIE';
let email = '';
if (zahlung.method === 'paypal' && (fristAbgelaufen || rest === null)) {
  const warum = fristAbgelaufen
    ? `Zahlung ${alterTage} Tage alt, Mollie erstattet PayPal nur bis ${frist} Tage`
    : `Mollie bietet keine Erstattung mehr an (Zahlung ${alterTage} Tage alt)`;
  if (!config.payoutsAktiv) {
    vermerk('FRIST_ABGELAUFEN', `PayPal über Mollie: ${warum}. Payouts nicht aktiv – ${betrag.toFixed(2)} ${waehrung} manuell erstatten`, { betrag });
    return weiter('KEINER');
  }
  email = String(zahlung.details?.consumerAccount || src.paypalEmail || '').trim();
  if (!email.includes('@')) {
    vermerk('ZAHLUNG_PRUEFEN', `PayPal über Mollie: ${warum}. Payout nicht möglich: keine PayPal-E-Mail des Zahlers (weder bei Mollie noch in der PayPal-Suche)`, { betrag });
    return weiter('KEINER');
  }
  if (!$('Token holen (PayPal)').isExecuted) {
    vermerk('FEHLER', `PayPal über Mollie: ${warum}. Payout nicht möglich: PayPal wurde in diesem Lauf nicht abgefragt (kein Token)`, { betrag });
    return weiter('KEINER');
  }
  weg = 'PAYOUT';
} else {
  if (fristAbgelaufen) {
    vermerk('FRIST_ABGELAUFEN', `Mollie (${zahlung.method}): Zahlung ${alterTage} Tage alt, Erstattung nur bis ${frist} Tage – ${betrag.toFixed(2)} ${waehrung} manuell erstatten`, { betrag });
    return weiter('KEINER');
  }
  if (rest === null || betrag > rest + 0.005) {
    vermerk('MANUELL_ERSTATTEN', rest === null
      ? `Mollie bietet für diese Zahlung (${zahlung.method}) keine Erstattung über die API an – ${betrag.toFixed(2)} ${waehrung} manuell erstatten`
      : `Mollie erstattet höchstens noch ${rest.toFixed(2)} ${waehrung}, berechnet ${betrag.toFixed(2)} – manuell prüfen`, { betrag });
    return weiter('KEINER');
  }
}

const vorgang = `produktentfernung-wc-${src.bestellnummer}-${src.skus.join('+')}`;

// Doppelschutz wie bei PayPal: nur ohne Protokoll-Eintrag oder wenn der letzte Versuch ABGELEHNT war
const protokoll = $('Protokoll laden (Mollie)').all().map(i => i.json);
const lesefehler = protokoll.find(r => r.error);
if (lesefehler) {
  vermerk('ZAHLUNG_PRUEFEN', 'Protokoll nicht lesbar – keine Erstattung ohne Doppelschutz: ' + JSON.stringify(lesefehler.error).slice(0, 200), { betrag });
  return weiter('KEINER');
}
const eintrag = protokoll.find(r => r.vorgang === vorgang);
if (eintrag && eintrag.status !== 'ABGELEHNT') {
  const offen = ['RESERVIERT', 'UNKLAR'].includes(eintrag.status) ? ' – Ergebnis beim Zahlungsanbieter prüfen' : '';
  vermerk(eintrag.weg === 'PAYOUT' ? 'BEREITS_AUSGEZAHLT' : 'BEREITS_ERSTATTET',
    `Laut Protokoll: ${eintrag.weg || ''} ${eintrag.status} seit ${String(eintrag.createdAt).slice(0, 10)}${eintrag.referenz ? ', Referenz ' + eintrag.referenz : ''}${offen}`,
    { betrag, weg: eintrag.weg || weg, referenz: eintrag.referenz || '' });
  return weiter('KEINER');
}

const vorhaben = weg === 'PAYOUT' ? `per Payout an ${email} senden` : 'über Mollie erstatten';
if (config.modus !== 'SCHARF') {
  vermerk('TROCKENLAUF', `würde ${betrag.toFixed(2)} ${waehrung} ${vorhaben} (${zahlung.method}, Zahlung ${alterTage} Tage alt)`,
    { betrag, weg, empfaenger: email });
  return weiter('KEINER');
}

// Test-Limit: im Modus SCHARF nur die ersten Config.testLimit Vorgänge je Zahlungsweg – Mollie-Erstattungen und
// PayPal-Payouts getrennt gezählt (Payouts zusammen mit der PayPal-Schleife). Der Rest wird nur geprüft.
const limit = Number(config.testLimit) || 0;
const zaehler = weg === 'PAYOUT' ? 'testPayPal' : 'testMollie';
sd.lauf = sd.lauf || {};
if (limit > 0 && (sd.lauf[zaehler] || 0) >= limit) {
  vermerk('NICHT_VERARBEITET', `Test-Limit (${limit}) erreicht – würde ${betrag.toFixed(2)} ${waehrung} ${vorhaben} (${zahlung.method}, Zahlung ${alterTage} Tage alt)`,
    { betrag, weg, empfaenger: email });
  return weiter('KEINER');
}
sd.lauf[zaehler] = (sd.lauf[zaehler] || 0) + 1;

if (weg === 'PAYOUT') {
  // Payout: neue Zahlung an die PayPal-E-Mail des Zahlers.
  // sender_batch_id und PayPal-Request-Id schützen 30 Tage vor Doppelzahlung, danach das Protokoll.
  const payoutBody = {
    sender_batch_header: {
      sender_batch_id: vorgang,
      recipient_type: 'EMAIL',
      email_subject: config.payoutBetreff,
      email_message: config.payoutNachricht
    },
    items: [{
      recipient_type: 'EMAIL',
      amount: { value: betrag.toFixed(2), currency: waehrung },
      receiver: email,
      note: `${config.notizAnKunde} Bestellung ${src.bestellnummer}`,
      sender_item_id: String(src.bestellnummer).slice(0, 63)
    }]
  };
  return weiter('PAYOUT', { vorgang, betrag, waehrung, email, payoutBody: JSON.stringify(payoutBody) });
}

// Erstattung: Idempotency-Key = Vorgang, Mollie liefert bei Wiederholung innerhalb einer Stunde die erste Antwort
const refundBody = {
  amount: { currency: waehrung, value: betrag.toFixed(2) },
  description: String(config.notizAnKunde).slice(0, 255),
  metadata: { bestellnummer: src.bestellnummer, vorgang }
};
return weiter('MOLLIE', {
  vorgang,
  betrag,
  waehrung,
  molliePaymentId: zahlung.id,
  refundBody: JSON.stringify(refundBody)
});

// Wertet die Mollie-Erstattung aus und bereitet den Protokoll-Eintrag vor.
// Bewusst kein throw: der Loop geht weiter, der Report zeigt den Fehler.
const resp = $input.first().json;
const src = $('Mollie prüfen + Weg wählen').first().json;
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.done)) sd.done = [];

// Mollie antwortet mit Content-Type application/hal+json – je nach n8n-Einstellung kommt der Body als Text an
const alsObjekt = b => {
  if (b && typeof b === 'object') return b;
  if (typeof b !== 'string' || !b.trim()) return {};
  try { return JSON.parse(b); } catch (e) { return { parseFehler: 'Antwort nicht lesbar: ' + b.slice(0, 150) }; }
};
const r = alsObjekt(resp.body);
const fehlerText = x => {
  const b = alsObjekt(x.body);
  return [b.title, b.detail, b.field ? 'Feld ' + b.field : '', b.parseFehler, x.error?.message].filter(Boolean).join(' | ').slice(0, 400);
};
const antwort = resp.statusCode ? 'HTTP ' + resp.statusCode : 'keine Antwort';
const wiederholt = String(resp.headers?.['idempotent-replayed'] || '') === 'true';

// 201 = Erstattung angelegt. Refund-Status laut Mollie: queued, pending, processing, refunded, failed, canceled
let status;
let protokollStatus;
let grund = '';
if (resp.statusCode === 201 && r.id) {
  const gescheitert = ['failed', 'canceled'].includes(r.status);
  status = r.status === 'refunded' ? 'ERSTATTET' : gescheitert ? 'FEHLER' : 'ERSTATTUNG_AUSSTEHEND';
  // failed/canceled: kein Geld geflossen -> neuer Versuch erlaubt
  protokollStatus = gescheitert ? 'ABGELEHNT' : String(r.status).toUpperCase();
  if (status !== 'ERSTATTET') grund = `Mollie-Status ${r.status}${status === 'ERSTATTUNG_AUSSTEHEND' ? ' – Mollie führt die Erstattung noch aus' : ''}`;
  if (wiederholt) grund = [grund, 'Erstattung bestand bereits (gleicher Idempotency-Key)'].filter(Boolean).join(' · ');
} else if (resp.statusCode === 409) {
  // Gleiche Anfrage läuft noch: offen, ob Mollie erstattet -> UNKLAR sperrt weitere Versuche
  status = 'FEHLER';
  protokollStatus = 'UNKLAR';
  grund = `Mollie-Erstattung: ${antwort} ${fehlerText(resp)} – Ergebnis unklar, in Mollie prüfen`;
} else if (resp.statusCode >= 400 && resp.statusCode < 500) {
  // Abgelehnt, kein Geld geflossen (z. B. Zahlart nicht erstattbar, Frist abgelaufen, Guthaben zu gering)
  status = 'FEHLER';
  protokollStatus = 'ABGELEHNT';
  grund = `Mollie-Erstattung abgelehnt: ${antwort} ${fehlerText(resp)} – manuell erstatten`;
} else {
  status = 'FEHLER';
  protokollStatus = 'UNKLAR';
  grund = `Mollie-Erstattung: ${antwort} ${fehlerText(resp)} – Ergebnis unklar, in Mollie prüfen`;
}

const erstattet = r.amount?.value !== undefined ? Number(r.amount.value) : null;
if (status !== 'FEHLER' && erstattet !== null && Math.abs(erstattet - src.betrag) > 0.01) {
  grund = [grund, `Erstattet ${erstattet.toFixed(2)}, erwartet ${src.betrag.toFixed(2)} – prüfen`].filter(Boolean).join(' · ');
}

sd.done.push({
  bestellnummer: src.bestellnummer,
  status,
  grund: grund.slice(0, 500),
  weg: 'MOLLIE',
  transaktionsId: src.transaktionsId,
  zahlungsdatum: src.zahlungsdatum,
  zahlungsBetrag: src.zahlungsBetrag,
  captureStatus: src.captureStatus,
  zuordnung: src.zuordnung,
  betrag: erstattet ?? src.betrag,
  referenz: r.id || '',
  anbieterStatus: r.status || '',
  debug: `${src.debug} · Refund ${antwort}${r.status ? ' ' + r.status : ''}${wiederholt ? ' (wiederholt)' : ''}`,
  bearbeitetAm: new Date().toISOString()
});

// Für "Protokoll: Ergebnis (Mollie)" (Data Table)
return [{
  json: {
    vorgang: src.vorgang,
    bestellnummer: src.bestellnummer,
    weg: 'MOLLIE',
    transaktionsId: src.transaktionsId,
    betrag: erstattet ?? src.betrag,
    waehrung: src.waehrung,
    protokollStatus,
    referenz: r.id || '',
    protokollGrund: (grund || status).slice(0, 250)
  }
}];

// FLACHE DEBUG-TABELLE: eine Zeile pro Bestellung, in n8n als Table-View lesbar.
// Zeigt Zahlungsweg, Zuordnung, Antworten der Anbieter und den Protokoll-Eintrag – nur zum Ansehen, geht nicht in die Mail.
const config = $('Config').first().json.config;
const protokoll = $('Protokoll für Report laden').all().map(i => i.json).filter(r => r.vorgang);
// Neuester Eintrag je Bestellung
const protokollJe = new Map();
for (const r of protokoll) {
  const alt = protokollJe.get(r.bestellnummer);
  if (!alt || String(r.updatedAt || r.createdAt) > String(alt.updatedAt || alt.createdAt)) protokollJe.set(r.bestellnummer, r);
}

// Bearbeitete und problematische Fälle zuerst, reine Einordnung danach
const RANG = s => s === 'FEHLER' ? 0
  : ['ERSTATTET', 'ERSTATTUNG_AUSSTEHEND', 'AUSZAHLUNG_ANGESTOSSEN', 'TROCKENLAUF', 'NICHT_VERARBEITET'].includes(s) ? 1 : 2;

const rows = $input.all().map(i => i.json)
  .sort((a, b) => RANG(a.status) - RANG(b.status) || String(a.status).localeCompare(String(b.status))
    || String(a.bestellnummer).localeCompare(String(b.bestellnummer)));

return rows.map(r => {
  const p = protokollJe.get(r.bestellnummer);
  return { json: {
    modus:               config.modus,
    bestellnummer:       r.bestellnummer,
    status:              r.status,
    fall:                r.fall || null,
    // --- Zahlung laut Export ---
    zahlungsweg:         r.zahlungsweg || null,
    zahlungsartExport:   r.zahlungsart || null,
    transaktionsIdExport: r.transaktionsIdExport || null,
    // --- Zahlung beim Anbieter ---
    zuordnung:           r.zuordnung || null,
    transaktionsId:      r.transaktionsId || null,
    bestellwert:         r.bestellwert,
    gezahlt:             r.zahlungsBetrag === '' ? null : r.zahlungsBetrag,
    zahlungsstatus:      r.captureStatus || null,
    zahlungsdatum:       r.zahlungsdatum || null,
    // --- Erstattung ---
    weg:                 r.weg || null,
    berechnet:           r.erstattungsbetrag === '' ? null : r.erstattungsbetrag,
    betrag:              r.betrag === '' ? null : r.betrag,
    referenz:            r.referenz || null,
    anbieterStatus:      r.anbieterStatus || null,
    // --- Protokoll (Data Table) ---
    protokoll:           p ? `${p.weg || ''} ${p.status} (${String(p.updatedAt || p.createdAt).slice(0, 16)})`.trim() : null,
    // --- Technik ---
    debug:               r.debug || null,
    grund:               r.grund || null
  } };
});

// Ordnet die geladenen Mollie-Zahlungen und -Orders den gesuchten Bestellungen zu.
// Treffer: Bestellnummer steht in den Metadaten, in der Beschreibung (z. B. "Order 1808742") oder als orderNumber (Mollie-Order)
// UND Betrag = Bestellwert UND Zahlung vom Vortag bis +suchPufferTage nach dem Bestelldatum.
// Bestellungen mit Mollie-ID aus dem Export kommen direkt dazu.
const config = $('Config').first().json.config;
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.done)) sd.done = [];
sd.lauf = sd.lauf || {};
const suche = sd.mollieSuche || [];
const direkt = sd.mollieDirekt || [];
const TAG = 86400000;

// Mollie antwortet mit Content-Type application/hal+json. Je nach n8n-Einstellung kommt eine Seite als Objekt,
// als Text oder als Text in "data" an – hier immer in ein Objekt bringen.
const alsObjekt = j => {
  const text = typeof j === 'string' ? j : (j && typeof j.data === 'string' ? j.data : null);
  if (text === null) return j && j.data && typeof j.data === 'object' && !j._embedded ? j.data : (j || {});
  try { return JSON.parse(text); } catch (e) { return { error: { message: 'Mollie-Antwort nicht lesbar: ' + text.slice(0, 150) } }; }
};
// Die Lade-Nodes laufen nur, wenn gesucht wird
const seiten = name => { try { return $(name).all().map(i => alsObjekt(i.json)); } catch (e) { return []; } };
const zahlungsSeiten = seiten('Mollie-Zahlungen laden');
const orderSeiten = seiten('Mollie-Orders laden');
// Fehlerhafte Antworten (z. B. Orders API nicht verfügbar) für die Lauf-Info merken
const fehler = [...zahlungsSeiten, ...orderSeiten].filter(s => s.status >= 400 || s.error)
  .map(s => `${s.status || ''} ${s.title || s.error?.message || ''}${s.detail ? ': ' + s.detail : ''}`.trim());

// Mögliche Bestellnummern eines Mollie-Objekts
const nummernVon = obj => {
  const t = new Set();
  let md = obj.metadata;
  if (typeof md === 'string') { try { md = JSON.parse(md); } catch (e) { md = { text: md }; } }
  for (const v of Object.values(md || {})) if (['string', 'number'].includes(typeof v)) for (const m of String(v).match(/\d+/g) || []) t.add(m);
  for (const m of String(obj.description || '').match(/\d+/g) || []) t.add(m);
  if (obj.orderNumber) t.add(String(obj.orderNumber).trim());
  return t;
};

const gesucht = new Set(suche.map(o => o.bestellnummer));
const kandidaten = new Map();
const merke = (obj, quelle) => {
  for (const nr of nummernVon(obj)) {
    if (!gesucht.has(nr)) continue;
    if (!kandidaten.has(nr)) kandidaten.set(nr, []);
    kandidaten.get(nr).push({
      id: obj.id, orderId: obj.orderId || '', quelle, status: obj.status,
      betrag: Number(obj.amount?.value), waehrung: obj.amount?.currency,
      datum: obj.paidAt || obj.createdAt || ''
    });
  }
};
let anzahlZahlungen = 0;
let anzahlOrders = 0;
for (const s of zahlungsSeiten) for (const p of s._embedded?.payments || []) { anzahlZahlungen++; merke(p, 'Beschreibung/Metadaten'); }
for (const s of orderSeiten) for (const o of s._embedded?.orders || []) { anzahlOrders++; merke(o, 'Mollie-Order'); }

sd.lauf.mollieZahlungenGeladen = anzahlZahlungen;
sd.lauf.mollieOrdersGeladen = anzahlOrders;
sd.lauf.mollieZuordnung = {};
if (fehler.length) sd.lauf.mollieLadefehler = [...new Set(fehler)].slice(0, 3).join(' | ');
const zaehle = k => { sd.lauf.mollieZuordnung[k] = (sd.lauf.mollieZuordnung[k] || 0) + 1; };

const vermerk = (o, status, grund, extra = {}) => sd.done.push({
  bestellnummer: o.bestellnummer, status, grund: String(grund).slice(0, 500), ...extra, bearbeitetAm: new Date().toISOString()
});
const url = id => config.mollieBaseUrl + (id.startsWith('ord_') ? `/v2/orders/${encodeURIComponent(id)}?embed=payments` : `/v2/payments/${encodeURIComponent(id)}`);

const items = direkt.map(o => { zaehle(o.zuordnung || 'Transaktions-ID'); return { json: { ...o, mollieUrl: url(o.mollieId) } }; });

for (const o of suche) {
  const start = new Date(o.bestelldatum).getTime() - TAG;
  const ende = new Date(o.bestelldatum).getTime() + (config.suchPufferTage + 1) * TAG;
  const alle = kandidaten.get(o.bestellnummer) || [];
  // Zahlung einer Mollie-Order nicht doppelt zählen: die Zahlung (tr_) hat Vorrang vor der Order (ord_)
  const zahlungsIdsZuOrders = new Set(alle.filter(k => k.orderId).map(k => k.orderId));
  const eindeutig = alle.filter((k, i) => !(k.id.startsWith('ord_') && zahlungsIdsZuOrders.has(k.id))
    && alle.findIndex(x => x.id === k.id) === i);
  const imZeitraum = eindeutig.filter(k => { const t = new Date(k.datum).getTime(); return t >= start && t <= ende; });
  const passend = imZeitraum.filter(k => Math.abs(k.betrag - o.bestellwert) <= 0.01 && k.waehrung === o.waehrung);
  // Bezahlte bevorzugen (abgebrochene Versuche derselben Bestellung haben oft denselben Betrag)
  const bezahlt = passend.filter(k => k.status === 'paid' || k.status === 'completed' || k.status === 'shipping' || k.status === 'authorized');
  const treffer = bezahlt.length ? bezahlt : passend;
  const debug = `Mollie-Suche: ${anzahlZahlungen} Zahlungen, ${anzahlOrders} Orders · Kandidaten ${eindeutig.length}, im Zeitraum ${imZeitraum.length}, Betrag passt ${passend.length}`;
  const beiPayPal = o.paypalGesucht ? ` Bei PayPal gesucht: ${o.paypalGesucht}.` : '';

  if (treffer.length === 1) {
    zaehle(treffer[0].quelle);
    items.push({ json: { ...o, mollieId: treffer[0].id, mollieUrl: url(treffer[0].id), zuordnung: treffer[0].quelle, debug } });
  } else if (treffer.length > 1) {
    zaehle('mehrdeutig');
    vermerk(o, 'TRANSAKTION_PRUEFEN', `${treffer.length} Mollie-Zahlungen passen: ${treffer.map(k => k.id).join(', ')}`, { debug });
  } else if (imZeitraum.length) {
    zaehle('Betrag abweichend');
    vermerk(o, 'BETRAG_PRUEFEN', `Mollie-Zahlung zur Bestellnummer gefunden (${imZeitraum.map(k => `${k.id} ${k.betrag.toFixed(2)}`).join(', ')}), Bestellwert laut Export ${Number(o.bestellwert).toFixed(2)}`, { debug });
  } else {
    zaehle('keine');
    vermerk(o, 'NICHT_GEFUNDEN', `${o.paypalGesucht ? 'Weder bei PayPal noch bei Mollie gefunden.' + beiPayPal : 'Bei Mollie nicht gefunden.'} Bei Mollie: keine Zahlung mit Bestellnummer ${o.bestellnummer} zwischen Vortag und +${config.suchPufferTage} Tagen${eindeutig.length ? ` (${eindeutig.length} außerhalb des Zeitraums)` : ''}`, { debug });
  }
}

// Keine Mollie-Zahlung zum Abfragen: Steuer-Item ohne mollieUrl -> IF leitet direkt zum Report
return items.length ? items : [{ json: { mollie: 0 } }];

// Wertet den Payout im Mollie-Zweig aus (PayPal über Mollie, älter als die Mollie-Frist) und bereitet den Protokoll-Eintrag vor.
// Gleiche Auswertung wie "Auszahlung prüfen" in der PayPal-Schleife.
// PayPal bearbeitet Payouts asynchron: PENDING heißt angenommen, nicht ausgezahlt.
const resp = $input.first().json;
const src = $('Mollie prüfen + Weg wählen').first().json;
const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.done)) sd.done = [];

const body = resp.body || {};
const kopf = body.batch_header || {};
const fehlerText = x => [
  x.body?.name,
  x.body?.message,
  ...(x.body?.details || []).map(d => [d.field, d.issue, d.description].filter(Boolean).join(': ')),
  x.body?.debug_id ? 'debug_id ' + x.body.debug_id : '',
  x.error?.message
].filter(Boolean).join(' | ').slice(0, 400);

const antwort = resp.statusCode ? 'HTTP ' + resp.statusCode : 'keine Antwort';

// Batch-Status laut PayPal: DENIED, PENDING, PROCESSING, SUCCESS, CANCELED
const angelegt = resp.statusCode === 201 && Boolean(kopf.payout_batch_id);
const ok = angelegt && kopf.batch_status !== 'DENIED';
// sender_batch_id in den letzten 30 Tagen schon verwendet: PayPal lehnt ab und verlinkt den ursprünglichen Payout
const duplikat = !angelegt && (
  (body.links || []).some(l => /\/v1\/payments\/payouts\//.test(String(l.href))) ||
  /duplicate/i.test(`${body.name} ${body.message}`)
);
// 4xx bzw. DENIED = abgelehnt, kein Geld geflossen -> neuer Versuch erlaubt.
// 5xx oder keine Antwort: offen, ob PayPal ausgezahlt hat -> UNKLAR sperrt weitere Versuche.
const abgelehnt = !ok && !duplikat && ((angelegt && kopf.batch_status === 'DENIED') || (resp.statusCode >= 400 && resp.statusCode < 500));

let status;
let protokollStatus;
let grund;
if (ok) {
  status = 'AUSZAHLUNG_ANGESTOSSEN';
  protokollStatus = kopf.batch_status || 'PENDING';
  grund = `Payout-Status ${kopf.batch_status} – Abschluss in PayPal prüfen`;
} else if (duplikat) {
  status = 'BEREITS_AUSGEZAHLT';
  protokollStatus = 'DUPLIKAT';
  grund = 'PayPal: Payout mit derselben sender_batch_id existiert bereits – ' + fehlerText(resp);
} else if (abgelehnt) {
  status = 'FEHLER';
  protokollStatus = 'ABGELEHNT';
  grund = angelegt ? `Payout von PayPal abgelehnt (Status DENIED, ${kopf.payout_batch_id})` : `Payout: ${antwort} ${fehlerText(resp)}`;
} else {
  status = 'FEHLER';
  protokollStatus = 'UNKLAR';
  grund = `Payout: ${antwort} ${fehlerText(resp)} – Ergebnis unklar, in PayPal prüfen`;
}

sd.done.push({
  bestellnummer: src.bestellnummer,
  status,
  grund: grund.slice(0, 500),
  weg: 'PAYOUT',
  transaktionsId: src.transaktionsId,
  zahlungsdatum: src.zahlungsdatum,
  zahlungsBetrag: src.zahlungsBetrag,
  captureStatus: src.captureStatus,
  zuordnung: src.zuordnung,
  betrag: src.betrag,
  empfaenger: src.email,
  referenz: kopf.payout_batch_id || '',
  anbieterStatus: kopf.batch_status || '',
  debug: `${src.debug} · Payout ${antwort}${kopf.batch_status ? ' ' + kopf.batch_status : ''}${body.debug_id ? ' · debug_id ' + body.debug_id : ''}`,
  bearbeitetAm: new Date().toISOString()
});

// Für "Protokoll: Ergebnis" (Data Table)
return [{
  json: {
    vorgang: src.vorgang,
    bestellnummer: src.bestellnummer,
    weg: 'PAYOUT',
    transaktionsId: src.transaktionsId,
    betrag: src.betrag,
    waehrung: src.waehrung,
    protokollStatus,
    referenz: kopf.payout_batch_id || '',
    protokollGrund: grund.slice(0, 250)
  }
}];
